; Note that the variables have to be set up first
; because they're used for some macro definitions
	include "ps4.options.asm"

	cpu 68000
	include "ps4.macrosetup.asm"

	include "ps4.constants.asm"

	
StartOfRom:
	if (*) <> 0
	fatal	"Start of ROM is at address $\{*}, but it should be at address 0."
	endif

VectorTable:
	dc.l	System_Stack, EntryPoint, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	HInt_Jump, ErrorTrap, VInt, ErrorTrap
	dc.l	Trap00Exception, Trap01Exception, Trap02Exception, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap
	dc.l	ErrorTrap, ErrorTrap, ErrorTrap, ErrorTrap

Header:
	dc.b	"SEGA GENESIS    " ; Console name
	dc.b 	"(C)SEGA 1994.NOV" ; Copyright/Date
	dc.b 	"PHANTASY STAR The end of the millennium         " ; Domestic name
	dc.b 	"PHANTASY STAR The end of the millennium         " ; International name
	dc.b 	"GM MK-1307 -00"   ; Version

Checksum:
	dc.w	$5CB		; Checksum
	dc.b 	"J               " ; I/O Support
	dc.l 	StartOfRom		; ROM Start

ROMEndLoc:
	dc.l	EndOfRom-1		; ROM End
	dc.l 	RAM_Start&$FFFFFF		; RAM Start
	dc.l 	RAM_End&$FFFFFF		; RAM End
	dc.l 	$5241F820		; SRAM ID
	dc.l 	SRAM_Start		; SRAM start address
	dc.l 	SRAM_End		; SRAM end address
	dc.b 	"            "	; Modem support
	dc.b 	"                                        "	; Notes
	dc.b 	"4               "
EndOfHeader:
	if (*) <> $200
	fatal	"End of header is at address $\{*}, but it should be at address $200. The header + the vector table must be exactly 512 bytes long"
	endif


ErrorTrap:
	bra.s	ErrorTrap


; ========================================================================================
; Trap #0 Exception
;
; Clears address pointed to by a0 a number of times defined in d7
; ========================================================================================
Trap00Exception:
	moveq	#0, d0
	move.l	d0, (a0)+
	dbf	d7, Trap00Exception
	rte

; ========================================================================================
; Trap #1 Exception
;
; Copies content of address pointed to by a0 to address pointed to by a1 a number of times defined in d7
; ========================================================================================
Trap01Exception:
	move.w	(a0)+, (a1)+
	dbf	d7, Trap01Exception
	rte

; -------------------
	rte
; -------------------

; ========================================================================================
; Trap #2 Exception
;
; Get address offset in lookup table pointed to by a0 and jump to that address
; ========================================================================================
Trap02Exception:
	add.w	d0, d0
	adda.w	(a0,d0.w), a0
	jsr	(a0)
	rte


EntryPoint:

; ------------------------------------------------------------------------------
; START OF TEMPLATE CODE
;
; This section contains initialization code used in many Mega Drive games; it's template code and
; some of the initial parameters are overwritten in the main game program.

	tst.l	(HW_Port_1_Control-1).l	; test ports A and B control
	bne.s	PortAB_OK
	tst.w	(HW_Expansion_Control-1).l	; test port C control
PortAB_OK:
	bne.s	PortC_OK
	lea	SetupValues(pc), a5
	movem.w	(a5)+, d5-d7
	movem.l	(a5)+, a0-a4
	move.b	HW_Version-Z80_Bus_Request(a1), d0	; get hardware version
	andi.b	#$F, d0
	beq.s	SkipSecurity	; branch if we're using the first hardware model
	move.l	#"SEGA", Security_Addr-Z80_Bus_Request(a1)	; satisfy the TMSS
SkipSecurity:
	move.w	(a4), d0	; test VDP to see if it works -- if you don't write SEGA to the security address and the first 4 bytes of the header are not SEGA, the VDP will lock up
	moveq	#0, d0
	movea.l	d0, a6
	move.l	a6, usp
	moveq	#(VDPInitValues_End-VDPInitValues)-1, d1
VDPInitLoop:
	move.b	(a5)+, d5	; add $8000 to value
	move.w	d5, (a4)	; move value to VDP register
	add.w	d7, d5		; next register
	dbf	d1, VDPInitLoop

	move.l	(a5)+, (a4)	; set VRAM write mode
	move.w	d0, (a3)	; clear the screen
	move.w	d7, (a1)	; stop the Z80
	move.w	d7, (a2)	; reset the Z80
-
	btst	d0, (a1)	; has the Z80 stopped?
	bne.s	-		; if not, branch
	moveq	#(Z80StartupCode_End-Z80StartupCode)-1, d2
Z80InitLoop:
	move.b	(a5)+, (a0)+
	dbf	d2, Z80InitLoop
	move.w	d0, (a2)
	move.w	d0, (a1)	; start the Z80
	move.w	d7, (a2)	; reset the Z80
ClrRAMLoop:
	move.l	d0, -(a6)
	dbf	d6, ClrRAMLoop	; clear the entire RAM
	move.l	(a5)+, (a4)	; set VDP display mode and increment
	move.l	(a5)+, (a4)	; set VDP to CRAM write
	moveq	#$1F, d3
ClrCRAMLoop:
	move.l	d0, (a3)
	dbf	d3, ClrCRAMLoop	; clear the CRAM
	move.l	(a5)+, (a4)
	moveq	#$13, d4
ClrVSRAMLoop:
	move.l	d0, (a3)
	dbf	d4, ClrVSRAMLoop
	moveq	#(PSGInitValues_End-PSGInitValues)-1, d5
PSGInitLoop:
	move.b	(a5)+, PSG_Input-VDP_Data_Port(a3)	; reset the PSG
	dbf	d5, PSGInitLoop
	move.w	d0, (a2)
	movem.l	(a6), d0-a6
	move	#$2700, sr
PortC_OK:
	bra.s	MainGameProgram


SetupValues:
	dc.w	$8000
	dc.w	$3FFF
	dc.w	$0100

	dc.l	Z80_RAM
	dc.l	Z80_Bus_Request
	dc.l	Z80_Reset
	dc.l	VDP_Data_Port
	dc.l	VDP_Control_Port

VDPInitValues:
	dc.b	$04		; Command $8004 - HInt off, Enable HV counter read
	dc.b	$14		; Command $8114 - Display off, VInt off, DMA on, PAL off
	dc.b	$30		; Command $8230 - Scroll A Address $C000
	dc.b	$3C		; Command $833C - Window Address $F000
	dc.b	$07		; Command $8407 - Scroll B Address $E000
	dc.b	$6C		; Command $856C - Sprite Table Addres $D800
	dc.b	$00		; Command $8600 - Null
	dc.b	$00		; Command $8700 - Background color Pal 0 Color 0
	dc.b	$00		; Command $8800 - Null
	dc.b	$00		; Command $8900 - Null
	dc.b	$FF		; Command $8AFF - Hint timing $FF scanlines
	dc.b	$00		; Command $8B00 - Ext Int off, VScroll full, HScroll full
	dc.b	$81		; Command $8C81 - 40 cell mode, shadow/highlight off, no interlace
	dc.b	$37		; Command $8D37 - HScroll Table Address $DC00
	dc.b	$00		; Command $8E00 - Null
	dc.b	$01		; Command $8F01 - VDP auto increment 1 byte
	dc.b	$01		; Command $9001 - 64x32 cell scroll size
	dc.b	$00		; Command $9100 - Window H left side, Base Point 0
	dc.b	$00		; Command $9200 - Window V upside, Base Point 0
	dc.b	$FF		; Command $93FF - DMA Length Counter $FFFF
	dc.b	$FF		; Command $94FF - See above
	dc.b	$00		; Command $9500 - DMA Source Address $0
	dc.b	$00		; Command $9600 - See above
	dc.b	$80		; Command $9700	- See above + VRAM fill mode
VDPInitValues_End:

	dc.l	$40000080	; DMA - VRAM write mode

Z80StartupCode:
	save
	cpu Z80
	xor	a
	ld	bc, 1FD9h
	ld	de, 27h
	ld	hl, 26h
	ld	sp, hl
	ld	(hl), a
	ldir
	pop	ix
	pop	iy
	ld	i, a
	ld	r, a
	pop	de
	pop	hl
	pop	af
	ex	af, af'
	exx
	pop	bc
	pop	de
	pop	hl
	pop	af
	ld	sp, hl
	di
	im	1
	ld	(hl), 0E9h
	jp	(hl)

	restore
	padding off
Z80StartupCode_End:

	dc.w	$8104	; VDP display mode
	dc.w	$8F02	; VDP auto-increment
	dc.l	$C0000000	; CRAM write
	dc.l	$40000010	; VSRAM write

PSGInitValues:
	dc.b	$9F, $BF, $DF, $FF
PSGInitValues_End:

; END OF TEMPLATE CODE
; ------------------------------------------------------------------------------

MainGameProgram:
	tst.w	(VDP_Control_Port).l

-
	move.w	(VDP_Control_Port).l, d0	; read VDP status register
	nop
	btst	#1, d0	; is DMA taking place?
	bne.s	-	; loop if it is

	lea	(VDP_Data_Port).l, a5
	lea	(VDP_Control_Port).l, a6
	move	#$2700, sr		; disable interrupts
	move.w	#$100, (Z80_Bus_Request).l	; stop Z80
	move.w	#$100, (Z80_Reset).l	; reset Z80
-
	btst	#0, (Z80_Bus_Request).l
	bne.s	-		; loop until the Z80 has stopped

	cmpi.l	#"init", (Init_String_Addr).w	; is it the first time we are here since console power on?
	beq.s	MainGameProgram_Continue					; if not, branch
	lea	($FFFFFF00).w, a0
	move.w	#$3F, d7
-
	clr.l	(a0)+	; clear last 255 bytes of RAM
	dbf	d7, -
	move.l	#"init", (Init_String_Addr).w	; flag this part as initialized

MainGameProgram_Continue:
	move.w	#$100, (Z80_Bus_Request).l	; stop Z80
-
	btst	#0, (Z80_Bus_Request).l
	bne.s	-		; loop until the Z80 has stopped

	lea	(RAM_Start).l, a0
	move.w	#$3FBF, d7
-
	clr.l	(a0)+	; clear all except the last 255 bytes of RAM
	dbf	d7, -

	jsr	(InitJoypads).l
	jsr	(MainGameVDPSetup).l
	clr.b	($FFFFECC5).w
	movem.l	d0-a6, -(sp)
	jsr	(JumpTo_InitSoundDriver).l
	movem.l	(sp)+, d0-a6
	move.w	#$4EF9, (HInt_Jump).w	; machine code for jmp
	move.l	#HInt, (HInt_Addr).w
	move	#$2100, sr		; enable interrupts
	jsr	(DoRegionLock).l		; remove this line to disable region lock

MainGameLoop:
	move.w	(Game_Mode_Index).w, d0
	movea.l	GameModePtrs(pc,d0.w), a0
	jsr	(a0)
	bra.s	MainGameLoop

; --------------------------------------
GameModePtrs:
	dc.l	GameMode_Sega		; 0
	dc.l	GameMode_Title	; 4
	dc.l	GameMode_LoadFieldMap	; 8
	dc.l	GameMode_Field	; $C
	dc.l	GameMode_LoadBattle	; $10
	dc.l	GameMode_Battle	; $14
	dc.l	GameMode_JmpToVInt_Prepare	; $18
; --------------------------------------

DoRegionLock:
	move.b	(HW_Version).l, d0	; get hardware version
	andi.b	#$C0, d0		; get Video Type and Export bits
	cmpi.b	#$80, d0		; is Video Type NTSC and Export bit 1 (not Japanese)?
	beq.s	+				; if so, return and process game normally
	bsr.w	NotNTSCError	; otherwise display message that game is for NTSC systems only
	rts
+
	rts


NotNTSCError:
	jsr	(MainGameVDPSetup).l
	move.l	#$C0000000, (VDP_Control_Port).l	; write to CRAM
	moveq	#$3F, d7
-
	move.w	#$E, (VDP_Data_Port).l
	dbf	d7, -

	move.w	#$1D, d7
loc_432:
	jsr	(VInt_Prepare).l
	dbf	d7, loc_432

	jsr	(PalFadeOut_ClrSpriteTbl).l
	jsr	(ClearPlanes_A_B_Buf).l
	move.b	#2, (HW_Write_Mode).l	; ROM, write protected
	lea	(loc_4DA).l, a1
loc_456:
	move.w	(a1)+, d0
	bmi.s	loc_46C
	move.l	(a1)+, d1
	movea.l	d1, a0
	jsr	(LoadVRAMAddressFromTileNumber).l
	jsr	(NemDecomp).l
	bra.s	loc_456

loc_46C:
	lea	(Pal_TitleScreen).l, a0
	lea	(Palette_Table_Buffer).w, a1
	move.w	#$3F, d0
loc_47A:
	move.w	(a0)+, (a1)+
	dbf	d0, loc_47A
	clr.w	(Palette_Table_Buffer+$5C).w
	jsr	(Pal_FadeIn).l
	lea	(loc_4E2).l, a0
	moveq	#7, d0
	moveq	#$A, d1
	move.w	#$4000, d2
	moveq	#0, d3
	moveq	#0, d4
	jsr	(LoadWindowTiles).l
	lea	(loc_4FE).l, a0
	moveq	#7, d0
	moveq	#$C, d1
	move.w	#$4000, d2
	moveq	#0, d3
	moveq	#0, d4
	jsr	(LoadWindowTiles).l
	lea	(loc_512).l, a0
	moveq	#7, d0
	moveq	#$E, d1
	move.w	#$4000, d2
	moveq	#0, d3
	moveq	#0, d4
	jsr	(LoadWindowTiles).l
loc_4D2:
	jsr	(DMAPlane_A_VInt).l
	bra.s	loc_4D2

loc_4DA:
	dc.w	$0681
	dc.l	ArtNem_Font
	dc.w	$FFFF

; ====================================================================
	charset	'A', 'Z', 1
	charset	'a', 'z', 57
	charset '0', '9', 27
	charset ' ', 0

loc_4E2:
	dc.b	"DEVELOPED FOR USE ONLY WITH"
	dc.b	$FF

	even

loc_4FE:
	dc.b	"       NTSC GENESIS"
	dc.b	$FF

	even

loc_512:
	dc.b	"         SYSTEMS"
	dc.b	$FF

	charset
; ====================================================================

	even

; --------------------------------------------------------------------
VInt:
	tst.b	(VInt_Flag).w
	beq.w	VInt_Skip		; skip if flag is not set
	move.w	(a6), (VDP_Status_Reg).w	; save VDP status register
	btst	#3, (VDP_Status_Reg+1).w	; is V blanking occurring?
	beq.w	VInt_Skip				; if not, skip

	move.w	#$100, (Z80_Bus_Request).l	; stop the Z80
-
	btst	#0, (Z80_Bus_Request).l
	bne.s	-					;  wait until the Z80 has stopped

	lea	(VDP_Data_Port).l, a5
	lea	(VDP_Control_Port).l, a6
	clr.w	($FFFFECBA).w
	bsr.w	loc_63E
	move.l	#$40000010, (a6)	; write to VSRAM
	move.w	(Camera_Y_Pos_FG).w, (a5)	; vertical scroll for plane A
	move.w	(Camera_Y_Pos_BG).w, (a5)	; vertical scroll for plane B
	move.l	#$74000003, (a6)	; write to H scroll table
	move.w	(Camera_X_Pos_FG).w, d0	; horizontal scroll for Plane A
	swap	d0
	move.w	(Camera_X_Pos_BG).w, d0	; horizontal scroll for Plane B
	neg.w	d0
	swap	d0
	neg.w	d0
	swap	d0
	move.l	d0, (a5)

	; DMA 68k to VDP
	move.w	(VDP_Reg1_Val).w, d4
	bset	#4, d4	; enable DMA
	move.w	d4, (a6)
	move.l	#$94019340, (a6)	; length = $280 bytes
	move.l	#$96FE9500, (a6)
	move.w	#$977F, (a6)		; RAM Sprite Table = $7FFE00<<1 = $FFFC00
	move.w	#$7000, (a6)	; write to Sprite Attribute Table
	move.w	#$83, -(sp)
	move.w	(sp)+, (a6)		; last write must be done from RAM for this DMA transfer
	move.w	(VDP_Reg1_Val).w, (a6)	; disable DMA

	; the 2 instructions below are probably useless
	move.l	#$70000003, (a6)
	move.w	(Sprite_Table_Buffer).w, -$4(a6)

	tst.b	(CRAM_Update_Flag).w
	beq.s	CRAM_Update_Skip	; skip if flag for updating CRAM is not set

	; DMA 68k to VDP
	move.w	(VDP_Reg1_Val).w, d4
	bset	#4, d4	; enable DMA
	move.w	d4, (a6)
	move.l	#$94009340, (a6)	; length = $80 bytes
	move.l	#$96FD9580, (a6)
	move.w	#$977F, (a6)		; RAM Palette Table = $7FFD80<<1 = $FFFB00
	move.w	#$C000, (a6)	; write to CRAM
	move.w	#$80, -(sp)
	move.w	(sp)+, (a6)
	move.w	(VDP_Reg1_Val).w, (a6)	; disable DMA

	; again, probably useless instructions
	move.l	#$C0000000, (a6)
	move.w	(Palette_Table_Buffer).w, -$4(a6)

CRAM_Update_Skip:
	jsr	(CheckDMAQueue).l
	bsr.w	ReadJoypads
	clr.w	(Z80_Bus_Request).l	; start the Z80
	jsr	(UpdateRNGSeed).l
	addq.w	#1, (VInt_Frame_Count).w
	cmpi.w	#99, (VInt_Frame_Count).w
	ble.s	+
	clr.w	(VInt_Frame_Count).w
+
	addq.w	#1, (Main_Frame_Count).w
	clr.b	(VInt_Flag).w


VInt_Skip:
	tst.b	($FFFFEE5B).w
	beq.s	+
	move	#$2300, sr
+
	movem.l	d0-a6, -(sp)
	jsr	(JumpTo_UpdateSound).l
	movem.l	(sp)+, d0-a6
	rte
; --------------------------------------------------------------------



loc_63E:
	cmpi.l	#HInt, (HInt_Addr).w
	bne.s	loc_64A
	rts

loc_64A:
	move.w	($FFFFECB8).w, d0
	jmp	loc_652(pc,d0.w)

loc_652:
	bra.w	loc_69E
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_6DC
	bra.w	loc_716
	bra.w	loc_728
	bra.w	loc_73E
	bra.w	loc_752

loc_69E:
	move.l	($FFFFECBC).w, d0
	lea	($FFFF60E0).l, a0
	move.w	#$6F, d7
loc_6AC:
	move.l	d0, d1
	swap	d1
	move.w	d1, (a0)
	lea	-$2(a0), a0
	sub.l	($FFFFECBC).w, d0
	dbf	d7, loc_6AC
	move.l	($FFFFECBC).w, d0
	lea	($FFFF60E0).l, a0
	move.w	#$6F, d7
loc_6CC:
	move.l	d0, d1
	swap	d1
	move.w	d1, (a0)+
	add.l	($FFFFECBC).w, d0
	dbf	d7, loc_6CC
	rts
loc_6DC:
	cmpi.w	#$E0, ($FFFFECB6).w
	bls.s	loc_6EA
	move.w	#1, ($FFFFECB6).w
loc_6EA:
	lea	(Chunk_Table).l, a0
	move.w	($FFFFECB6).w, d7
	move.w	d7, d6
	subq.w	#1, d7
loc_6F8:
	move.w	#0, (a0)+
	dbf	d7, loc_6F8
