	rts

HInt:
	rte

HInt2:
	movem.l	d0/a0, -(sp)
	lea	(Chunk_Table).l, a0
	move.w	($FFFFECBA).w, d0
	lea	(a0,d0.w), a0
	move.l	#$40000010, (VDP_Control_Port).l
	move.w	(a0), d0
	add.w	(Camera_Y_Pos_FG).w, d0
	move.w	d0, (VDP_Data_Port).l
	move.w	(a0), d0
	add.w	(Camera_Y_Pos_BG).w, d0
	move.w	d0, (VDP_Data_Port).l
	addq.w	#2, ($FFFFECBA).w
