; -----------------------------------------------------------------
ReadJoypads:
	lea	(Joypad_Ctrl).w, a0
	lea	(HW_Port_1_Data).l, a1
	bsr.s	ReadJoypad

; Fix input bug where you skip an option if you press Confirm while holding down a directional button
	if bugfixes=1
	move.b	(Joypad_Held).w, d0
	andi.b	#ButtonUp_Mask|ButtonDown_Mask|ButtonLeft_Mask|ButtonRight_Mask, d0
	beq.s	.clear
	move.b	(Joypad_Pressed).w, d0
	andi.b	#ButtonUp_Mask|ButtonDown_Mask|ButtonLeft_Mask|ButtonRight_Mask, d0
	bne.s	.addinput
	else
	tst.b	(Joypad_Held).w
	beq.s	.clear
	tst.b	(Joypad_Pressed).w
	bne.s	.addinput
	endif
	subq.b	#1, (Button_Held_Timer).w
	bpl.s	.ret
	clr.b	(Button_Held_Timer).w
	subq.b	#1, (Button_Held_Frames).w
	bpl.s	.ret
.addinput:
	move.b	#4, (Button_Held_Frames).w
	andi.b	#ButtonUp_Mask|ButtonDown_Mask|ButtonLeft_Mask|ButtonRight_Mask, d1
	or.b	d1, -(a0)
	bra.s	.ret
.clear:
	clr.b	(Button_Held_Frames).w
	move.b	#$14, (Button_Held_Timer).w
.ret:
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
ReadJoypad:
	move.b	#0, (a1)	; read joypad data port
	nop					; bus synchronization
	nop
	move.b	(a1), d0	; get joypad data - Start/A
	lsl.b	#2, d0		; shift them so they are at the 2 highest bits
	andi.b	#$C0, d0	; make sure only Start and A are set
	move.b	#$40, (a1)	; read joypad data port again
	nop					; bus synchronization
	nop
	move.b	(a1), d1	; get joypad data - C/B/Dpad
	andi.b	#$3F, d1	; C/B/Dpad in bits 0-5
	or.b	d1, d0		; OR d0 and d1 so that you get all button bits together
	not.b	d0			; for the hardware bit 0 for a Control means pressed, while 1 means released; to be more intuitive, we flip bits so that they mean the opposite
	move.w	(Button_Mappings_Index).w, d2	; get index of the mappings we chose in the Buttons window
	lea	(ButtonMappingsOffs).l, a1
	adda.w	(a1,d2.w), a1
	jsr	(a1)
	move.b	d0, d1	; move buttons in d1
	move.b	(a0), d2	; get previously read buttons
	eor.b	d2, d0		; switch off buttons we were pressing
	move.b	d1, (a0)+	; store buttons in memory (held state)
	and.b	d1, d0		; AND with current buttons
	move.b	d0, (a0)+	; store buttons in memory (pressed state)
	rts
; -----------------------------------------------------------------



; =================================================================
ButtonMappingsOffs:
	dc.w	ButtonMappings_1-ButtonMappingsOffs	; 0
	dc.w	ButtonMappings_2-ButtonMappingsOffs	; 2
	dc.w	ButtonMappings_3-ButtonMappingsOffs	; 4
	dc.w	ButtonMappings_4-ButtonMappingsOffs	; 6
	dc.w	ButtonMappings_5-ButtonMappingsOffs	; 8
	dc.w	ButtonMappings_6-ButtonMappingsOffs	; $A
; =================================================================


; -----------------------------------------------------------------
ButtonMappings_2:
	moveq	#0, d2
	move.b	d0, d1		; buttons
	andi.b	#$9F, d0	; clear C and A bits
	andi.b	#$60, d1	; get C and A bits
	lsl.b	#2, d1		; shift by 2
	bcc.s	+			; if A bit was not set, branch
	moveq	#$40, d2	; if we pressed A, put it before C
	or.b	d2, d1		; OR the value in d1
+
	lsr.b	#1, d1		; shift values by 1 to get them back in the cleared bits
	or.b	d1, d0		; final result

; Defaults uses the first entry in the Button window, that is A = CAMP, C = SPEAK, B = CANCL
ButtonMappings_1:
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
ButtonMappings_3:
	moveq	#0, d2
	move.b	d0, d1		; buttons
	andi.b	#$CF, d0	; clear B and C bits
	andi.b	#$30, d1	; get B and C bits
	lsl.b	#3, d1		; shift by 3
	bcc.s	+			; branch if C bit was cleared
	moveq	#$40, d2	; if we pressed C, put it before B
	or.b	d2, d1		; OR the value in d1
+
	lsr.b	#2, d1		; shift values by 2 to get them back in the cleared bits
	or.b	d1, d0		; final result
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
ButtonMappings_4:
	bsr.w	ButtonMappings_5	; first switch B with A
	bra.s	ButtonMappings_2	; then switch B with C (B replaces A here)
; -----------------------------------------------------------------


; -----------------------------------------------------------------
ButtonMappings_5:
	moveq	#0, d2
	move.b	d0, d1		; buttons
	andi.b	#$AF, d0	; clear B and A bits
	andi.b	#$50, d1	; get B and A bits
	lsl.b	#2, d1		; shift by 2 -- B is already in A's place
	bcc.s	+			; branch if A was cleared
	moveq	#$10, d2	; otherwise put it in B's place
	or.b	d2, d1		; OR the value in d1
+
	or.b	d1, d0		; final result
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
ButtonMappings_6:
	bsr.s	ButtonMappings_5	; first switch B with A
	bra.s	ButtonMappings_3	; then replace C with A (A replaces B here)
; -----------------------------------------------------------------


