Battle_UpdateRedCursor2:
	move.w	#$E6E8, d3	; red tile
	move.w	#$E6E7, d4	; blue tile
+
	move.w	(a1), d0	; get option index
	andi.w	#$FFFC, (a1)	; clear lowest 2 bits so we can add the index
	andi.w	#3, d0
	move.w	d0, d2
	lsl.w	#8, d2
	move.w	d4, (a0,d2.w)
	btst	#ButtonUp, d5
	beq.s	loc_F12
	move.b	#SFXID_MovingCursor, (Sound_Index&$FFFFFF).l
	subq.w	#1, d0
	bge.s	loc_F28
	move.w	d1, d0
	bra.s	loc_F28
loc_F12:
	btst	#ButtonDown, d5
	beq.s	loc_F28
	move.b	#SFXID_MovingCursor, (Sound_Index&$FFFFFF).l
	addq.w	#1, d0
	cmp.w	d1, d0
	ble.s	loc_F28
	clr.w	d0
loc_F28:
	add.w	d0, (a1)
	lsl.w	#8, d0
loc_F2C:
	btst	#ButtonCamp, d5
	bne.s	loc_F72			; if you press the interaction button, show red tile
	btst	#ButtonSpeak, d5
	bne.s	loc_F72			; or if you press the menu button
	subq.w	#1, ($FFFF41D2).l	; subtract 1 to display timer
	bgt.s	loc_F60				; if still greater than 0, branch
	addq.w	#1, ($FFFF41D4).l
	move.w	#$19, ($FFFF41D2).l	; reset timer
	andi.w	#1, ($FFFF41D4).l	; values can only be 0 and 1
	beq.s	loc_F60				; if 0, branch
	move.w	#$F, ($FFFF41D2).l	; when not showing the red tile, make timer shorter
loc_F60:
	move.w	d4, (a0,d0.w)	; blue tile
	tst.b	(Joypad_Held).w
	bne.s	loc_F72			; show red tile as long as you hold down a button
	tst.w	($FFFF41D4).l
	bne.s	loc_F76			; if value is 1, show blue tile
loc_F72:
	move.w	d3, (a0,d0.w)	; red tile
loc_F76:
	rts
