Battle_FillTechList:
	movem.l	d0-a4, -(sp)
	lea	(Battle_Tech_List).l, a2
	movea.l	a2, a0
	clr.l	(a0)+
	clr.l	(a0)+
	clr.l	(a0)+
	clr.l	(a0)+
	moveq	#$F, d7
	lea	techs+$F(a4), a1	; load technique list starting from the last one learned
	lea	(TechniqueData).l, a0
-
	movea.l	a0, a3
	moveq	#0, d0
	move.b	(a1), d0	; get character's technique
	beq.s	++	; if there's none, process previous one
	move.w	d0, d1
	subq.w	#1, d1
	lsl.w	#3, d1		; technique size is 8
	adda.w	d1, a3		; get offset
	btst	#4, $2(a3)
	beq.s	++	; branch if 'in-battle' bit is not set
	moveq	#0, d1
	move.b	$1(a3), d1	; TP cost
	cmp.w	curr_tp(a4), d1
	bls.s	+	; branch if TP cost is lower or same than character's current TP
	ori.b	#$80, d0	; sign bit set to indicate it can't be used
+
	move.b	d0, (a2)+	; store technique
+
	subq.l	#1, a1		; previous technique
	dbf	d7, -

	movem.l	(sp)+, d0-a4
	rts
; -----------------------------------------------------------------


