Battle_FillSkillList:
	movem.l	d0-a4, -(sp)
	lea	(Battle_Skill_List).l, a2
	movea.l	a2, a0
	clr.l	(a0)+
	clr.l	(a0)+
	clr.l	(a0)+
	clr.l	(a0)+
	moveq	#7, d7
	lea	skills+7(a4), a1	; load skill list starting from the last one learned
	lea	(SkillData).l, a0
	moveq	#7, d5
loc_10A0:
	movea.l	a0, a3
	moveq	#0, d0
	move.b	(a1), d0	; get character's skill
	beq.s	loc_1110	; if there's none, process previous one
	move.w	d0, d1
	subq.w	#1, d1
	lsl.w	#3, d1		; technique size is 8
	adda.w	d1, a3		; get offset
	btst	#4, $2(a3)
	beq.s	loc_1110	; branch if 'in-battle' bit is not set
	tst.b	$1(a3)
	bpl.s	loc_10FA	; if sign bit is not set (meaning a weapon is not required), branch
	movem.l	d0/a0, -(sp)
	move.b	right_hand(a4), d0
	jsr	(Battle_GetItemType).l
	move.w	d0, d1
	movem.l	(sp)+, d0/a0
	subq.w	#1, d1
	cmpi.b	#3, d1
	bls.s	loc_10FA	; if we have a weapon equipped, branch
	movem.l	d0/a0, -(sp)
	move.b	left_hand(a4), d0
	jsr	(Battle_GetItemType).l
	move.w	d0, d1
	movem.l	(sp)+, d0/a0
	subq.w	#1, d1
	cmpi.b	#3, d1
	bls.s	loc_10FA
	ori.b	#$80, d0
loc_10FA:
	lea	curr_skill_uses(a4), a3
	move.w	d5, d1
	add.w	d1, d1
	move.b	(a3,d1.w), d1
	bne.s	loc_110C	; if number of uses is greater than 0, branch
	ori.b	#$80, d0
loc_110C:
	move.b	d0, (a2)+	; store skill ID
	move.b	d1, (a2)+	; store number of current skill uses
loc_1110:
	subq.w	#1, d5
	subq.l	#1, a1
	dbf	d7, loc_10A0
	movem.l	(sp)+, d0-a4
	rts
