; -----------------------------------------------------------------
; d2 = effect
; -----------------------------------------------------------------
Ability_GetEffectAndRange:
	tst.w	d2
	beq.w	loc_61B0	; return if ability has no effect
	lea	(Battle_Ability_Effects).l, a3
	move.w	(Current_Actor_Index).l, d0
	jsr	(Battle_GetFighterAddr).l	; get character's address
	movea.l	a0, a2		; a2 = actor's address
	movea.l	stats_addr(a0), a1	; a1 = character's stats
	moveq	#0, d0
	move.b	(Battle_Ability_Range).l, d0
	lea	AbilityRangeOffs(pc), a0
	trap	#2
	bra.s	Ability_ProcessRange
; -----------------------------------------------------------------


; =================================================================
AbilityRangeOffs:
	dc.w	AbilityRange_Varied-AbilityRangeOffs	; 0
	dc.w	AbilityRange_Single-AbilityRangeOffs	; 1
	dc.w	AbilityRange_MultiEnemies-AbilityRangeOffs	; 2
	dc.w	AbilityRange_Self-AbilityRangeOffs	; 3
	dc.w	AbilityRange_Single-AbilityRangeOffs	; 4
	dc.w	AbilityRange_MultiChars-AbilityRangeOffs	; 5
	dc.w	AbilityRange_Single-AbilityRangeOffs	; 6
	dc.w	AbilityRange_MultiChars-AbilityRangeOffs	; 7
	dc.w	AbilityRange_Single-AbilityRangeOffs	; 8
	dc.w	AbilityRange_MultiChars-AbilityRangeOffs	; 9
; =================================================================


; -----------------------------------------------------------------
; This part dynamically chooses a target depending on who's acting
; -----------------------------------------------------------------
AbilityRange_Varied:
	moveq	#0, d7
	move.w	(Current_Target_Index).l, d6
	bpl.s	loc_6118
	cmpi.w	#5, (Current_Actor_Index).l
	bgt.s	loc_6114
	moveq	#6, d6
	moveq	#3, d7
	bra.s	loc_6118
loc_6114:
	moveq	#1, d6
	moveq	#4, d7
loc_6118:
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityRange_Single:
	move.w	(Current_Target_Index).l, d6
	moveq	#0, d7
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityRange_Self:
	move.w	(Current_Actor_Index).l, d6
	moveq	#0, d7
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityRange_MultiEnemies:
	moveq	#6, d6
	moveq	#3, d7
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityRange_MultiChars:
	moveq	#1, d6
	moveq	#4, d7
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d6 = Fighter ID ; can start from 1 if target is a character or 6 if
;		an enemy; can also be a specific if fighter is target was selected
; d7 = Loop count; 0 if single target; 3 when looping all enemies;
;		4 when looping all characters
; -----------------------------------------------------------------
Ability_ProcessRange:
	move.w	d6, d0	; get ID of target
	jsr	(Battle_GetFighterAddr).l
	tst.w	(a0)
	beq.s	loc_61AA		; skip if no fighter in this memory slot
	movea.l	stats_addr(a0), a0	; a0 = stats
	move.b	status(a0), d0	; d0 = status
	cmpi.w	#$16, d2
	beq.s	loc_6168
	cmpi.w	#$15, d2
	bne.s	loc_6162
	andi.b	#StatusDead_Mask|StatusAndroidDead_Mask, d0
	beq.s	loc_61AA		; branch if not dead
	bra.s	loc_6168
loc_6162:
	andi.b	#StatusDead_Mask|StatusAndroidDead_Mask, d0
	bne.s	loc_61AA			; branch if dead
loc_6168:
	cmpi.b	#4, (Battle_Ability_Range).l
	beq.s	.humans
	cmpi.b	#5, (Battle_Ability_Range).l
	beq.s	.humans		; branch if target is all humans
	cmpi.b	#6, (Battle_Ability_Range).l
	beq.s	.androids		; branch if target is all androids
	cmpi.b	#7, (Battle_Ability_Range).l
	bne.s	loc_61A2
.androids:
	cmpi.w	#ProfessionID_Android, profession(a0)
	bne.s	loc_61AA		; skip if not androids
	bra.s	loc_61A2
.humans:
	cmpi.w	#ProfessionID_Android, profession(a0)
	beq.s	loc_61AA		; skip if androids
loc_61A2:
	movea.l	a0, a4	; a4 = stats
	move.w	d2, -(sp)	; save effect on the stack
	bsr.s	Ability_GetEffect
	move.w	(sp)+, d2
loc_61AA:
	addq.w	#1, d6
	dbf	d7, Ability_ProcessRange
loc_61B0:
	rts


; -----------------------------------------------------------------
; d2 = effect
; a1 = stats' address
; a2 = actor's address
; a4 = target's stats address
; -----------------------------------------------------------------
Ability_GetEffect:
	moveq	#0, d3
	lea	AbilityEffectsOffs(pc), a0
	move.w	d2, d0
	trap	#2
	rts
; -----------------------------------------------------------------


; =================================================================
AbilityEffectsOffs:
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; 0
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; 1
	dc.w	AbilityEffect_Death-AbilityEffectsOffs	; 2
	dc.w	AbilityEffect_AttackDown-AbilityEffectsOffs	; 3
	dc.w	AbilityEffect_DefenseDown-AbilityEffectsOffs	; 4
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; 5
	dc.w	AbilityEffect_AgilityDown-AbilityEffectsOffs	; 6
	dc.w	AbilityEffect_SleepParalyze-AbilityEffectsOffs	; 7
	dc.w	AbilityEffect_SealTech-AbilityEffectsOffs	; 8
	dc.w	AbilityEffect_AttackUp-AbilityEffectsOffs	; 9
	dc.w	AbilityEffect_DefenseUp-AbilityEffectsOffs	; $A
	dc.w	AbilityEffect_MagicDefenseUp-AbilityEffectsOffs	; $B
	dc.w	AbilityEffect_AgilityUp-AbilityEffectsOffs	; $C
	dc.w	AbilityEffect_ElementResistanceUp-AbilityEffectsOffs	; $D
	dc.w	AbilityEffect_WakeUp-AbilityEffectsOffs	; $E
	dc.w	AbilityEffect_NormalLogic-AbilityEffectsOffs	; $F
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $10
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $11
	dc.w	AbilityEffect_NormalLogic-AbilityEffectsOffs	; $12
	if bugfixes=1
	dc.w	AbilityEffect_CurePoison-AbilityEffectsOffs	; $13
	dc.w	AbilityEffect_CureParalysis-AbilityEffectsOffs	; $14
	dc.w	AbilityEffect_Revive-AbilityEffectsOffs	; $15
	dc.w	AbilityEffect_ReviveFull-AbilityEffectsOffs	; $16
	else
	dc.w	AbilityEffect_RestoreAgiAndDex-AbilityEffectsOffs	; $13
	dc.w	AbilityEffect_RestoreAgiAndDex-AbilityEffectsOffs	; $14
	dc.w	AbilityEffect_RestoreAgiAndDex-AbilityEffectsOffs	; $15
	dc.w	AbilityEffect_RestoreAgiAndDex-AbilityEffectsOffs	; $16
	endif
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $17
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $18
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $19
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $1A
	dc.w	AbilityEffect_Poison-AbilityEffectsOffs	; $1B
	dc.w	AbilityEffect_Paralyze-AbilityEffectsOffs	; $1C
	dc.w	AbilityEffect_AndroidDeath-AbilityEffectsOffs	; $1D
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $1E
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $1F
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $20
	dc.w	AbilityEffect_DexterityDown-AbilityEffectsOffs	; $21
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $22
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $23
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $24
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $25
	dc.w	AbilityEffect_DexterityUp-AbilityEffectsOffs	; $26
	dc.w	AbilityEffect_RestoreStats-AbilityEffectsOffs	; $27
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $28
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $29
	dc.w	AbilityEffect_None-AbilityEffectsOffs	; $2A
	dc.w	AbilityEffect_IncreaseStats-AbilityEffectsOffs	; $2B
; =================================================================


; -----------------------------------------------------------------
AbilityEffect_None:
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_Death:
	btst	#StatusDead, status(a4)
	bne.s	+		; if target is already dead, branch
	move.b	#$42, d3
	bra.w	Battle_ProcessEffect
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_AttackDown:
	move.b	#$30, d3
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	AbilityEffect_None
	move.w	atk_pow(a4), atk_pow_battle(a4)
	sub.w	d1, atk_pow_battle(a4)	; decrease attack
	bhi.s	+
	clr.w	atk_pow_battle(a4)
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_DefenseDown:
	move.b	#$30, d3
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	AbilityEffect_None
	move.w	dfs_pow(a4), dfs_pow_battle(a4)
	sub.w	d1, dfs_pow_battle(a4)	; decrease defense
	bhi.s	+
	clr.w	dfs_pow_battle(a4)
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_AgilityDown:
	move.b	#$30, d3
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	+
	move.b	agility_mod(a4), agility_battle(a4)
	sub.b	d1, agility_battle(a4)	; decrease agility
	bhi.s	+
	move.b	#1, agility_battle(a4)
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_SleepParalyze:
	btst	#StatusAsleep, status(a4)
	bne.s	+
	btst	#StatusParalyzed, status(a4)
	bne.s	+
	move.b	#$44, d3
	bsr.w	Battle_ProcessEffect
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_SealTech:
	btst	#StatusTechSealed, status(a4)
	bne.s	+
	move.b	#$44, d3
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	+
	bset	#StatusTechSealed, status(a4)
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_AttackUp:
	cmpi.w	#4, (Ability_Effect_Type).w	; are we using an item?
	bne.s	+							; if not, branch
	cmpi.w	#ProfessionID_Android, profession(a4)
	beq.s	++					; if we are using an item, it has no effect on androids
+
	moveq	#0, d5
	move.b	(Battle_Ability_Range).l, d5
	bsr.w	Effect_CheckValidTarget
	tst.b	d5
	bne.s	+
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	+
	move.w	atk_pow(a4), atk_pow_battle(a4)
	add.w	d1, atk_pow_battle(a4)	; increase attack
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_DefenseUp:
	moveq	#0, d5
	move.b	(Battle_Ability_Range).l, d5
	bsr.w	Effect_CheckValidTarget
	tst.b	d5
	bne.s	+
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	+
	move.w	dfs_pow(a4), dfs_pow_battle(a4)
	add.w	d1, dfs_pow_battle(a4)	; increase defense
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_MagicDefenseUp:
	moveq	#0, d5
	move.b	(Battle_Ability_Range).l, d5
	bsr.w	Effect_CheckValidTarget
	tst.b	d5
	bne.s	+
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	+
	move.w	magic_dfs(a4), magic_dfs_battle(a4)
	add.w	d1, magic_dfs_battle(a4)	; increase magic defense
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_AgilityUp:
	moveq	#0, d5
	move.b	(Battle_Ability_Range).l, d5
	bsr.s	Effect_CheckValidTarget
	tst.b	d5
	bne.s	+
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	+
	move.b	agility_mod(a4), agility_battle(a4)
	add.b	d1, agility_battle(a4)	; increase agility
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_DexterityUp:
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.w	AbilityEffect_None
	move.b	dexterity_mod(a4), dexterity_battle(a4)
	add.b	d1, dexterity_battle(a4)
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_ElementResistanceUp:
	moveq	#0, d5
	move.b	(Battle_Ability_Range).l, d5
	bsr.s	Effect_CheckValidTarget
	tst.b	d5
	bne.s	+
	bsr.w	Battle_ProcessEffect
	move.b	$3(a0,d0.w), d0
	andi.w	#$FF, d0
	addi.w	#$2E, d0
	move.b	#1, (a4,d0.w)	; set element to 1 making target more resistant to that element
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_NormalLogic:
	moveq	#0, d5
	move.b	(Battle_Ability_Range).l, d5
	bsr.s	Effect_CheckValidTarget
	tst.b	d5
	bne.s	+
	bsr.w	Battle_ProcessEffect
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d5 = range
; a4 = target stats
;
; Returns
;
; d5 = flag; $00 = valid; $FF = not valid
; -----------------------------------------------------------------
Effect_CheckValidTarget:
	add.w	d5, d5
	move.w	EffectValidTargetOffs(pc,d5.w), d5
	jmp	EffectValidTargetOffs(pc,d5.w)
; -----------------------------------------------------------------


; =================================================================
EffectValidTargetOffs:
	dc.w	EffectTarget_None-EffectValidTargetOffs	; 0
	dc.w	EffectTarget_All-EffectValidTargetOffs	; 1
	dc.w	EffectTarget_All-EffectValidTargetOffs	; 2
	dc.w	EffectTarget_All-EffectValidTargetOffs	; 3
	dc.w	EffectTarget_Humans-EffectValidTargetOffs	; 4
	dc.w	EffectTarget_Humans-EffectValidTargetOffs	; 5
	dc.w	EffectTarget_Androids-EffectValidTargetOffs	; 6
	dc.w	EffectTarget_Androids-EffectValidTargetOffs	; 7
	dc.w	EffectTarget_All-EffectValidTargetOffs	; 8
	dc.w	EffectTarget_All-EffectValidTargetOffs	; 9
; =================================================================


; -----------------------------------------------------------------
EffectTarget_None:
	st	d5
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
EffectTarget_Humans:
	clr.b	d5
	cmpi.w	#5, $6(a4)
	bne.s	loc_63EA
	st	d5
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
EffectTarget_Androids:
	st	d5
	cmpi.w	#5, $6(a4)
	bne.s	loc_63EA
	clr.b	d5
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
EffectTarget_All:
	clr.b	d5
loc_63EA:
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_WakeUp:
	btst	#StatusAsleep, status(a4)
	beq.s	+
	bset	#7, status(a4)
	bra.w	Battle_ProcessEffect
+
	rts
; -----------------------------------------------------------------

; Fix: Check if you're affected by a bad status effect; if you're not, don't restore original
; agility and dexterity values
	if bugfixes=1
; -----------------------------------------------------------------
AbilityEffect_CurePoison:
	btst	#StatusPoisoned, status(a4)
	beq.s	AbilityEffect_CureEffect
	bra.s	AbilityEffect_CureRestoreStats

AbilityEffect_CureParalysis:
	btst	#StatusParalyzed, status(a4)
	beq.s	AbilityEffect_CureEffect
	bra.s	AbilityEffect_CureRestoreStats

AbilityEffect_Revive:
	btst	#StatusDead, status(a4)
	beq.s	AbilityEffect_CureEffect
	bra.s	AbilityEffect_CureRestoreStats

AbilityEffect_ReviveFull:
	btst	#StatusAndroidDead, status(a4)
	bne.s	AbilityEffect_CureRestoreStats
	btst	#StatusDead, status(a4)
	beq.s	AbilityEffect_CureEffect

AbilityEffect_CureRestoreStats:
	move.b	agility_mod(a4), agility_battle(a4)
	move.b	dexterity_mod(a4), dexterity_battle(a4)
AbilityEffect_CureEffect:
	bra.w	Battle_ProcessEffect
; -----------------------------------------------------------------
	else
; -----------------------------------------------------------------
AbilityEffect_RestoreAgiAndDex:
	move.b	agility_mod(a4), agility_battle(a4)
	move.b	dexterity_mod(a4), dexterity_battle(a4)
	bra.w	Battle_ProcessEffect
; -----------------------------------------------------------------
	endif

; -----------------------------------------------------------------
AbilityEffect_Poison:
	btst	#StatusPoisoned, status(a4)
	bne.s	+
	move.b	#$48, d3
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	+
	bset	#StatusPoisoned, status(a4)
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_Paralyze:
	btst	#1, status(a4)
	bne.s	+
	move.b	#$48, d3
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	+
	bset	#StatusParalyzed, status(a4)
	bclr	#StatusAsleep, status(a4)	; remove sleep
	move.b	#1, agility_battle(a4)		; lower agility to 1
	move.b	#1, dexterity_battle(a4)	; lower dexterity to 1
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_AndroidDeath:
	btst	#StatusAndroidDead, status(a4)
	bne.s	+
	move.b	#$48,d3
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.w	+
	bset	#StatusAndroidDead, status(a4)
	move.b	#1, agility_battle(a4)
	move.b	#1, dexterity_battle(a4)
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_DexterityDown:
	move.b	#$30, d3
	bsr.w	Battle_ProcessEffect
	tst.w	d0
	bmi.s	+
	move.b	dexterity_mod(a4), dexterity_battle(a4)
	sub.b	d1, dexterity_battle(a4)	; decrease dexterity
	bhi.s	+
	move.b	#1, dexterity_battle(a4)
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_RestoreStats:
	bsr.s	Battle_ProcessEffect
	movem.l	d7-a1, -(sp)
	lea	physical_prop+1(a4), a0
	lea	physical_prop(a4), a1
	moveq	#$D, d7
-
	move.b	(a0), (a1)
	addq.w	#2, a0
	addq.w	#2, a1
	dbf	d7, -
	move.b	strength_mod(a4), strength_battle(a4)
	move.b	mental_mod(a4), mental_battle(a4)
	move.b	agility_mod(a4), agility_battle(a4)
	move.b	dexterity_mod(a4), dexterity_battle(a4)
	move.w	atk_pow(a4), atk_pow_battle(a4)
	move.w	dfs_pow(a4), dfs_pow_battle(a4)
	move.w	magic_dfs(a4), magic_dfs_battle(a4)
	movem.l	(sp)+, d7-a1
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
AbilityEffect_IncreaseStats:
	bsr.s	Battle_ProcessEffect
	moveq	#20, d1			; increase all stats by 20
	add.b	d1, strength_battle(a4)
	add.b	d1, mental_battle(a4)
	add.b	d1, agility_battle(a4)
	add.b	d1, dexterity_battle(a4)
	add.w	d1, atk_pow_battle(a4)
	add.w	d1, dfs_pow_battle(a4)
	add.w	d1, magic_dfs_battle(a4)
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d0 = effect ID * 2
; -----------------------------------------------------------------
Battle_ProcessEffect:
	move.w	d0, d5
	lsr.w	#1, d5
	move.w	(Ability_Effect_Type).w, d0
	lea	EffectLogicOffs(pc), a0
	trap	#2
	rts
; -----------------------------------------------------------------


; =================================================================
EffectLogicOffs:
	dc.w	Effect_DoPhysicalAttack-EffectLogicOffs	; 0
	dc.w	Effect_DoEnemySkill-EffectLogicOffs	; 1
	dc.w	Effect_DoTechnique-EffectLogicOffs	; 2
	dc.w	Effect_DoSkill-EffectLogicOffs	; 3
	dc.w	Effect_DoItem-EffectLogicOffs	; 4
; =================================================================


; -----------------------------------------------------------------
Effect_DoItem:
	move.w	($FFFF4146).l, d0
	andi.w	#$FF, d0
	jsr	(Battle_GetItemOffset).l
	moveq	#0, d0
	moveq	#0, d1
	move.b	$1(a0), d1
	bra.s	loc_6598
; -----------------------------------------------------------------


; -----------------------------------------------------------------
Effect_DoSkill:
	lea	(SkillData-8).l, a0
	bra.s	Effect_SetupSkillParams
; -----------------------------------------------------------------


; -----------------------------------------------------------------
Effect_DoTechnique:
	move.w	ability(a2), d0
	lea	(TechniqueData-8).l, a0
	moveq	#0, d1
	move.b	mental_battle(a1), d1
	lsl.w	#3, d0
	tst.b	$4(a0,d0.w)
	bne.s	loc_659E
loc_6564:
	move.w	d6, d2
	add.w	d2, d2
	move.b	d5, -$2(a3,d2.w)
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
Effect_DoEnemySkill:
	lea	(EnemySkillData-8).l, a0
; -----------------------------------------------------------------


; -----------------------------------------------------------------
Effect_SetupSkillParams:
	move.w	ability(a2), d0
	lsl.w	#3, d0
	move.b	$1(a0,d0.w), d1	; stat type
	andi.w	#$7F, d1
	add.w	d1, d1
	move.w	AbilityStatsOffs(pc,d1.w), d1
	cmpi.w	#atk_pow_battle, d1
	bge.s	loc_6594
	move.b	(a1,d1.w), d1	; get power stat
	bra.s	loc_6598
loc_6594:
	move.w	(a1,d1.w), d1	; attack, defense and magic defense offsets are a word long, so it's move.w
; -----------------------------------------------------------------


; -----------------------------------------------------------------
loc_6598:
	tst.b	$4(a0,d0.w)
	beq.s	loc_6564	; skip if target resistance is ignored
loc_659E:
	move.b	$5(a0,d0.w), d3	; target element factor
	add.w	d3, d3
	addi.w	#$2E, d3
	move.b	(a4,d3.w), d3
	moveq	#0, d4
	move.b	$3(a0,d0.w), d4	; get hit chance
	moveq	#0, d2
	move.b	$4(a0,d0.w), d2	; get stat resistance offset
	add.w	d2, d2
	move.w	AbilityStatsOffs(pc,d2.w), d2
	cmpi.w	#atk_pow_battle, d2
	bge.s	loc_65CA
	move.b	(a4,d2.w), d2	; get resistance stat
	bra.s	loc_65CE
loc_65CA:
	move.w	(a4,d2.w), d2	; attack, defense and magic defense offsets are a word long, so it's move.w
loc_65CE:
	bra.w	loc_6652
; -----------------------------------------------------------------


; =================================================================
AbilityStatsOffs:
	dc.w	$0000	; 0
	dc.w	strength_battle	; 1
	dc.w	mental_battle	; 2
	dc.w	agility_battle	; 3
	dc.w	dexterity_battle	; 4
	dc.w	atk_pow_battle	; 5
	dc.w	dfs_pow_battle	; 6
	dc.w	magic_dfs_battle	; 7
; =================================================================


; -----------------------------------------------------------------
; a1 = stats' address
; a2 = actor's address
; a4 = target's stats address
; -----------------------------------------------------------------
Effect_DoPhysicalAttack:
	cmpi.w	#5, ($FFFF4142).l
	bgt.s	loc_6640
	swap	d2
	move.w	d2, d0
	move.w	d2, d1
	lea	(InventoryData+4).l, a0	; target stat offset
	jsr	(Battle_GetItemValue).l
	move.w	d0, d2
	add.w	d0, d0
	add.w	d0, d2
	move.b	$17(a4,d2.w), d2	; d2 = target stat
	lea	(InventoryData+5).l, a0	; element offset
	move.w	d1, d0
	jsr	(Battle_GetItemValue).l
	add.w	d0, d0
	move.b	$2E(a4,d0.w), d3	; d3 = target element factor
	lea	(InventoryData+3).l, a0	; hit chance offset
	move.w	d1, d0
	jsr	(Battle_GetItemValue).l
	moveq	#0, d4
	move.b	d0, d4				; d4 = hit chance
	lea	(InventoryData+1).l, a0	; power offset
	move.w	d1, d0
	jsr	(Battle_GetItemValue).l
	move.w	d0, d1				; d1 = item power
	bra.s	loc_6652
loc_6640:
	move.b	(a4,d3.w), d3
	moveq	#$70, d4
	moveq	#0, d1
	moveq	#0, d2
	move.b	$1A(a1), d1
	move.b	$1A(a4), d2
loc_6652:
	move.w	d1, -(sp)
	jsr	Battle_CalculateChances(pc)
	move.w	(sp)+, d1
	tst.w	d0
	bmi.s	loc_666E
	move.w	d6, d2
	add.w	d2, d2
	tst.b	-$2(a3,d2.w)
	beq.s	loc_666A
