; -----------------------------------------------------------------
; This subroutine is used for things such as hit/miss/critical hits, suprise attack/ambush and running away from battle.
; It returns a flag depending on the context
;
; Parameters
;
; d1 = Actor's parameter (e.g. Mental)
; d2 = Target's parameter
; d3 = Element factor (for attacks or escape, value is always 2)
; d4 = Lower bound; if random number is lower than this number, then it's a failure (e.g. miss)
; d5 = Upper bound; if random number is higher than this number, then it can be a critical hit or surprise attack
;
; Return values
;
; d0 = Flag; values can be as follows:
;
;    $00 = Regular such as normal attack, no surprise or ambush, etc.
;    $01 = Critical hits or surprise attacks
;    $FF = Failure such as attack miss
; -----------------------------------------------------------------
Battle_CalculateChances:
	jsr	(UpdateRNGSeed2).l
	andi.w	#$3F, d0	; number from 0 to 63
	sub.w	d2, d1	; subtract target's param from actor's param
	add.w	d1, d0	; add the difference to random number
	muls.w	d3, d0
	cmp.w	d4, d0
	ble.s	loc_B5C6	; if random number is less than lower bound, it's a failure
	cmp.w	d5, d0
	ble.s	loc_B5C2	; if random number is less than upper bound, it's regular action

; otherwise it can be a critical hit or a surprise attack
	moveq	#1, d0
	rts
loc_B5C2:
	moveq	#0, d0
	rts

loc_B5C6:
	moveq	#-1, d0
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; Parameters
;
; d1 = Attack or Mental power
; d2 = Defense power
; d3 = Element factor
; d4 = Damage from critical hits or technique/skill power
;
; Return values
;
; d0 = Total damage
; -----------------------------------------------------------------
Battle_CalculateDamage:
	movem.l	d1-d7, -(sp)
	moveq	#$F, d7
	moveq	#0, d6	; this holds total damage

; Generate a random number from 0 to 7 and add it to total damage (16 times)
-
	jsr	(UpdateRNGSeed2).l
	andi.w	#7, d0
	add.w	d0, d6
	dbf	d7, -

	addq.w	#8, d6	; add 8 to total damage
	muls.w	d1, d6	; multiply total damage by attack power
	lsr.w	#6, d6	; divide by 64
	add.w	d1, d6	; add attack power to total damage
	add.w	d4, d4
	add.w	d4, d6	; additional damage (e.g. critical hit)
	muls.w	d3, d6	; multiply by element value
	lsr.w	#2, d6	; divide total damage by 4
	sub.w	d2, d6	; subtract defense power from total damage
	move.w	d6, d0
	movem.l	(sp)+, d1-d7
	rts
; -----------------------------------------------------------------


