-
	jsr	(UpdateRNGSeed2).l
	andi.w	#7, d0
	add.w	d0, d6
	dbf	d7, -

	addq.w	#8, d6
	muls.w	d2, d6
	lsr.w	#6, d6
	add.w	d2, d6
	add.w	d3, d3
	add.w	d3, d6
	lsr.w	#1, d6
	move.w	d6, d0
	movem.l	(sp)+, d1-d7
	rts
; -----------------------------------------------------------------



