; empty space on both sides, so generate random number to choose side
	jsr	(UpdateRNGSeed2).l
	btst	#0, d0
	bne.s	loc_10D56	; if number's odd, branch
	bclr	#1, ($FFFFEE81).w	; clear right space empty bit if number is even
	bra.w	loc_10D5C
loc_10D56:
	bclr	#0, ($FFFFEE81).w	; clear left space empty bit
loc_10D5C:
	move.b	$3(a0), ability+1(a4)
loc_10D62:
	move.b	($FFFFEE81).w, d1
	rts
