; -----------------------------------------------------------------
; Find a free spot in the palette object memory so an object will be
; loaded later
;
; return values:
;   a0 = free palette object slot
; -----------------------------------------------------------------
Battle_LoadPaletteObj:
	lea	(Battle_Palette_Objects).l, a0
	moveq	#$1F, d7
-
	bclr	#1, $6(a0)
	tst.w	(a0)
	beq.s	+
	lea	palette_obj_size(a0), a0
	dbf	d7, -
	bset	#1, $6(a0)
+
	clr.b	$6(a0)
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
PaletteObj_Update:
	movea.l	pal_obj_data_addr(a4), a2	; get palette data
	move.b	pal_obj_frame_timer(a4), d0	; get timer
	cmp.b	(a2), d0					; did we reach limit and need to reset timer?
	bcs.s	+							; if not, branch
	clr.b	pal_obj_frame_timer(a4)		; reset timer
	addq.b	#1, pal_obj_frame(a4)		; increment index
+
	addq.b	#1, pal_obj_frame_timer(a4)	; increment timer
	moveq	#0, d0
	move.b	pal_obj_frame(a4), d0		; get current palette index
	cmp.b	$1(a2), d0					; did we reach the limit?
	bcs.s	+							; if not, branch
	moveq	#0, d0
	move.b	d0, pal_obj_frame(a4)		; reset index
	subq.b	#1, $7(a4)
	bgt.s	+
	clr.b	$7(a4)			; cap at 0
	bset	#0, $6(a4)
+
	moveq	#0, d7
	move.w	$2(a2), d7	; get counter
	subq.w	#1, d7
	add.w	d0, d0 		; multiply index by 2
	move.w	d0, d1		; save it in d1
	moveq	#0, d0
	moveq	#0, d3
	movea.l	pal_table_offs_addr(a4), a3	; get offsets for the palette table buffer
-
	move.b	(a3,d0.w), d3				; get offset
	lea	(Palette_Table_Buffer).w, a1
	adda.w	pal_line_offs(a4), a1		; palette line offset
	adda.w	d3, a1						; get palette
	move.w	$4(a2,d1.w), (a1)			; update value from the palette data
	moveq	#0, d2
	move.b	$1(a2), d2					; now palette number
	add.b	d2, d2						; multiply by 2
	add.w	d2, d1						; get next line in the palette data
	addq.b	#1, d0
	dbf	d7, -
	rts
; -----------------------------------------------------------------



