; -----------------------------------------------------------------
BattleObj_ClsRngAttackTrail:
	subq.w	#1, timer(a4)
	bgt.s	CloseRangeAttack_Return
	bset	#7, (a4)
	bne.s	BattleObj_ClsRngAttackTrailMain
	move.l	a4, -(sp)	; save object address
	movea.l	a4, a1
	movea.l	parent(a4), a4	; a4=character
	movea.l	stats_addr(a4), a0
	moveq	#0, d2
	moveq	#0, d3
	move.b	right_hand(a0), d2
	btst	#7, render_flags(a1)
	beq.s	+
	move.b	left_hand(a0), d2
+
	jsr	(Battle_LoadWeaponPalette).l
	movea.l	(sp)+, a4
	moveq	#0, d0	; delay
	jsr	Battle_LoadSoundObj_CloseRangeWpn(pc)
	lea	(Fighters_Hit_Flags).l, a0
	move.w	(Current_Target_Index).l, d6
	tst.b	-$1(a0,d6.w)
	bmi.s	loc_370C0	; branch if it's a miss
	beq.s	BattleObj_ClsRngAttackTrailMain	; branch if it's a regular attack

; load sound 3 other times for critical hits
	moveq	#4, d0		; delay
	jsr	Battle_LoadSoundObj_CloseRangeWpn(pc)
	moveq	#8, d0
	jsr	Battle_LoadSoundObj_CloseRangeWpn(pc)
	moveq	#$C, d0
	jsr	Battle_LoadSoundObj_CloseRangeWpn(pc)

BattleObj_ClsRngAttackTrailMain:
	bclr	#1, $2(a4)
	jsr	Battle_AnimateSprite(pc)
	btst	#2, $2(a4)
	beq.s	CloseRangeAttack_Return
CloseRangeAttack_Delete:
	clr.w	(a4)
CloseRangeAttack_Return:
	rts

loc_370C0:
	move.b	#SFXID_AttackMiss, sound(a1)
	move.w	#4, timer(a1)
	bra.s	CloseRangeAttack_Delete
