BattleObj_SlasherTrail:
	lea	(Fighters_Hit_Flags).l, a0
	move.w	(Current_Target_Index).l, d6
	tst.b	-$1(a0,d6.w)
	bmi.s	+
	subq.w	#1, timer(a4)
	bgt.s	++
	bclr	#1, render_flags(a4)
	jsr	Battle_AnimateSprite(pc)
	movea.l	parent(a4), a0	; a0=slasher
	move.w	battle_y_pos(a0), battle_y_pos(a4)
	move.w	battle_x_pos(a0), battle_x_pos(a4)
	tst.w	(a0)		; Is parent object still active?
	bne.s	++			; if so, branch
+
	clr.w	(a4)
+
	rts
