	bne.s	BattleObj_SoundMain
	bset	#1, $2(a4)

BattleObj_SoundMain:
	subq.w	#1, timer(a4)
	bgt.s	+
	move.b	sound(a4), (Sound_Index&$FFFFFF).l
	clr.w	(a4)
+
	rts
