; -----------------------------------------------------------------
BattleObj_SoundExtended:
	bset	#7, (a4)
	bne.s	BattleObj_SoundExtendedMain
	bset	#1, $2(a4)
	clr.w	routine(a4)

BattleObj_SoundExtendedMain:
	lea	SoundExtendedRoutines(pc), a0
	move.w	routine(a4), d0
	trap	#2
	rts
; -----------------------------------------------------------------


; =================================================================
SoundExtendedRoutines:
	dc.w	SoundExtended_Wait-SoundExtendedRoutines
	dc.w	SoundExtended_Play-SoundExtendedRoutines
; =================================================================


; -----------------------------------------------------------------
SoundExtended_Wait:
	subq.w	#1, timer(a4)
	bgt.s	+
	move.w	sound_length(a4), timer(a4)
	addq.w	#1, routine(a4)
/
	rts

SoundExtended_Play:
	subq.w	#1, timer(a4)
	ble.s	SoundExtended_Delete
	move.w	timer(a4), d0
	andi.w	#3, d0	; play sound every 4th frame
	bne.s	-
	move.b	sound(a4), (Sound_Index&$FFFFFF).l
	rts

SoundExtended_Delete:
	clr.w	(a4)
	rts
; -----------------------------------------------------------------


