; -----------------------------------------------------------------
; Main Earth object
; -----------------------------------------------------------------
BattleObj_Earth:
	bset	#7, (a4)		; initialize object
	bne.w	BattleObj_EarthMain	; branch if already initialized
	clr.w	routine(a4)
	clr.b	(Battle_Skill_Done_Flag).l	; clear object done flag
	bset	#1, render_flags(a4)
	move.w	#$3C, timer(a4)
	lea	(Battle_Objects_Memory+$1C0).w, a1
	jsr	(Battle_LoadObject).l
	move.w	#$108, battle_y_pos(a1)
	move.w	battle_x_pos(a4), battle_x_pos(a1)
	addi.w	#$12, battle_x_pos(a1)
	clr.b	mappings_duration(a1)
	clr.w	battle_mappings_idx(a1)
	move.w	#$544, (a1)	; load BattleObj_EarthAnim
	move.l	#Map_EarthUser, mappings_addr(a1)
	movea.l	parent(a4), a0	; a0=fighter
	move.l	a0, parent(a1)	; update parent for Earth 2 as well
	move.w	$E(a0), $1E(a1)
	move.b	#$60, $13(a1)
	move.w	#(SFXID_Eliminat<<8)|$10, d0	; $10 = timer before playing sound
	jsr	Battle_LoadSoundObj(pc)
	jsr	Battle_LoadAbilityAnimWithYPos(pc)
	move.w	#$14, timer(a1)
	move.l	#Map_Earth, mappings_addr(a1)
	move.w	#$A020, $1E(a1)
	move.w	battle_x_pos(a4), battle_x_pos(a1)
	lea	(Battle_Ability_Effects-2).l, a1
	move.w	(Current_Target_Index).l, d0
	add.w	d0, d0
	tst.w	(a1,d0.w)
	beq.s	BattleObj_EarthMain	; branch if Earth has no effect (i.d. failure)
	jsr	Battle_LoadAbilityAnim2(pc)	; load other object if successful (the 2 green half rings)
	move.w	#$20, timer(a1)
	move.l	#Map_Earth2, mappings_addr(a1)
	move.w	#$9B80, $1E(a1)
	move.w	battle_x_pos(a4), battle_x_pos(a1)
	move.w	#$64, timer(a4)	; increase timer
	move.w	#(SFXID_Rimit<<8)|$20, d0	; $20 = timer before playing sound
	jsr	Battle_LoadSoundObj(pc)

BattleObj_EarthMain:
	subq.w	#1, timer(a4)
	bge.s	+
	st	(Battle_Skill_Done_Flag).l	; set done flag
	subq.w	#1, $1C(a4)
	bge.s	++	; rts
	clr.w	(a4)
	movea.l	parent(a4), a0	; a0=fighter
	move.w	#$D, action_routine(a0)	; carry onto next routine for fighter
	bra.s	++	; rts

+
	cmpi.w	#$50, timer(a4)
	bne.s	+	; rts
	move.w	(Current_Target_Index).l, d0
	jsr	(Battle_GetFighterStatsAddr).l
	bset	#StatusAsleep, status(a0)
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; This is the character's animation for Earth
; -----------------------------------------------------------------
BattleObj_EarthAnim:
	bset	#7, (a4)
	bne.w	BattleObj_EarthAnimMain
	clr.w	routine(a4)

BattleObj_EarthAnimMain:
	lea	EarthAnimRoutines(pc), a0
	move.w	routine(a4), d0
	trap	#2
	rts
; -----------------------------------------------------------------

; =================================================================
EarthAnimRoutines:
	dc.w	EarthAnim_Animate-EarthAnimRoutines
	dc.w	EarthAnim_Wait-EarthAnimRoutines
; =================================================================


; -----------------------------------------------------------------
EarthAnim_Animate:
	jsr	CloseRangeObjs_AnimateSprite(pc)
	btst	#2, render_flags(a4)	; is animation done?
	beq.s	+				; if not, branch
	addq.w	#1, routine(a4)	; => EarthAnim_Wait
	movea.l	mappings_addr(a4), a0
	addq.w	#4, a0
	adda.w	$8(a0), a0
	move.l	(a0)+, d0
	lsr.l	#1, d0
	movea.l	parent(a4), a3	; a3=fighter
	move.w	vdp_dest_addr(a3), d1
	move.w	#$240, d2
	jsr	(QueueDMACommands).l
	move.l	a0, mappings(a4)
+
	rts
; -----------------------------------------------------------------


