EnemySprites_Animate:
	move.w	enm_spr_obj_id(a4), d0
	jsr	(Battle_GetFighterAddr).l
	btst	#3, render_flags(a4)
	bne.s	loc_40F48
	cmpi.b	#5, fighter_routine+1(a0)	; is enemy taking damage?
	beq.s	loc_40F48					; if so, return
	cmpi.b	#7, fighter_routine+1(a0)	; is enemy dead?
	bne.s	loc_40F34					; if not, branch

; when enemy is dead
	clr.w	(a4)		; delete sprite
	cmpi.w	#EnemyID_Haunt, fighter_id(a0)
	beq.s	+
	cmpi.w	#EnemyID_Spector, fighter_id(a0)
	beq.s	+
	cmpi.w	#EnemyID_Phantom, fighter_id(a0)
	bne.s	loc_40F48
+
	move.w	#$8010, (a4)	; => EnemySprites_Delete
	bra.s	loc_40F4A


loc_40F34:
	movea.l	stats_addr(a0), a0	; get stats
	move.b	status(a0), d0		; get status
	btst	#StatusAsleep, d0
	bne.s	loc_40F4A		; branch if enemy's asleep
	andi.b	#StatusDead_Mask|StatusAsleep_Mask|StatusAsleep2_Mask|StatusAndroidDead_Mask, d0	; is enemy dead or asleep?
	beq.s	loc_40F60	; if not, branch
loc_40F48:
	rts

