	subq.b	#1, enm_spr_frame_timer(a4)
	bpl.s	loc_41004
	move.b	$1(a1), enm_spr_frame_timer(a4)
	bset	#6, $2(a4)
	addq.b	#1, enm_spr_frame(a4)
	moveq	#0, d0
