;         GAME MODE = SEGA
; -----------------------------------------------------
GameMode_Sega:
	jsr	(PalFadeOut_ClrSpriteTbl).l
	move.w	#$8B00, (a6)	; Ext Int off, VScroll full, HScroll full
	jsr	(ClearPlanes_A_B_Buf).l
	lea	(MapEni_SegaLogo).l, a0
	move.w	#$10, d0
	lea	(RAM_Start).l, a1
	jsr	(EniDecomp).l

	lea	($FFFF8598).w, a1
	lea	(RAM_Start).l, a0
	moveq	#$11, d1
	moveq	#5, d2
	jsr	(PlaneMapToRAM).l
	jsr	(DMA_PlaneA).l
	lea	(Palette_Table_Buffer).w, a1
	moveq	#$1F, d7
	move.l	#$0E000E00, d0	; fill the whole palette table blue
-
	move.l	d0, (a1)+
	dbf	d7, -

	lea	(ArtNem_SegaLogo).l, a0
	moveq	#$10, d0
	jsr	(LoadVRAMAddressFromTileNumber).l
	jsr	(NemDecomp).l

	jsr	(Pal_FadeIn).l
	move.w	#$B3, d1
	move.b	#MusicID_EndOfTheMillennium, (Sound_Index).l
	clr.l	(RAM_Start).l

GameMode_SegaLoop:
	move.l	d1, -(sp)
	bsr.w	DoSegaPaletteCycling
	move.l	(sp)+, d1
	bsr.w	VInt_Prepare
	btst	#ButtonStart, (Joypad_Pressed).w
	dbne	d1, GameMode_SegaLoop

	bsr.w	loc_410E2
	bsr.w	VInt_Prepare
	jsr	(PalFadeOut_ClrSpriteTbl).l
	addq.w	#4, (Game_Mode_Index).w
	rts
