DoSegaPaletteCycling:
	lea	(Palette_Table_Buffer).w, a1
	cmpi.w	#5, ($FFFF0002).l
	bne.w	loc_411B0
	move.w	(RAM_Start).l, d0
	cmpi.w	#8, d0
	bcc.s	loc_41142
	lea	(loc_411B8).l, a0
	move.b	(a0,d0.w), d1
	lsl.w	#8, d1
	_move.w	d1, 0(a1)
	move.w	d1, $2(a1)
	bra.s	loc_411A4

loc_41142:
	cmpi.w	#$E, d0
	bcc.s	loc_41198
	subq.w	#8, d0
	move.w	d0, d2
	addq.w	#1, d2
	lea	(loc_411C0).l, a0
	lea	$4(a1), a2
	moveq	#4, d7
-
	move.b	(a0,d2.w), d1
	lsl.w	#8, d1
	move.w	d1, (a2)
	subq.w	#1, d2
	bpl.s	+
	moveq	#0, d2
+
	lea	$2(a2), a2
	dbf	d7, -

	move.w	d0, d2
	addq.w	#1, d2
	lea	(loc_411C8).l, a0
	lea	$1A(a1), a2
	moveq	#5, d7
-
	move.b	(a0,d2.w), d1
	move.b	d1, $1(a2)
	subq.w	#1, d2
	bpl.s	+
	moveq	#0, d2
+
	lea	-$2(a2), a2
	dbf	d7, -

	bra.s	loc_411A4

loc_41198:
	cmpi.w	#$15, d0
	bcc.s	loc_411B0
	addi.w	#$222, $2(a1)
loc_411A4:
	addq.w	#1, (RAM_Start).l
	clr.w	($FFFF0002).l
loc_411B0:
