; -------------------------------------------------------------------------
; Nemesis decompression subroutine, decompresses art directly to VRAM
; Inputs:
; a0 = art address
; a VDP command to write to the destination VRAM address must be issued
; before calling this routine
; -------------------------------------------------------------------------
NemDecomp:
	movem.l	d0-a1/a3-a5, -(sp)
	lea	(Nem_PCD_WriteRowToVDP).l, a3
	lea	(VDP_Data_Port).l, a4
	bra.s	NemDecomp_Main

; -------------------------------------------------------------------------
; Nemesis decompression subroutine, decompresses art to RAM
; Inputs:
; a0 = art address
; a4 = destination RAM address
; -------------------------------------------------------------------------
NemDecomp_ToRAM:
	movem.l	d0-a1/a3-a5, -(sp)
	lea	(Nem_PCD_WriteRowToRAM).l, a3

; -------------------------------------------------------------------------
; Main Nemesis decompression subroutine
; -------------------------------------------------------------------------
NemDecomp_Main:
	lea	(Nem_Code_Table).w, a1
	move.w	(a0)+, d2		; get number of patterns
	lsl.w	#1, d2
	bcc.s	+				; branch if the sign bit isn't set
	adda.w	#Nem_PCD_WriteRowToVDP_XOR-Nem_PCD_WriteRowToVDP, a3	; otherwise the file uses XOR mode
+
	lsl.w	#2, d2		; get number of 8-pixel rows in the uncompressed data
	movea.w	d2, a5		; and store it in a5 because there aren't any spare data registers
	moveq	#8, d3		; 8 pixels in a pattern row
	moveq	#0, d2
	moveq	#0, d4
	bsr.w	Nem_BuildCodeTable
	move.b	(a0)+, d5	; get first byte of compressed data
	asl.w	#8, d5		; shift up by a byte
	move.b	(a0)+, d5	; get second byte of compressed data
	move.w	#$10, d6	; set initial shift value
	bsr.s	Nem_ProcessCompressedData
	movem.l	(sp)+, d0-a1/a3-a5
	rts

; -------------------------------------------------------------------------
; Part of the Nemesis decompressor, processes the actual compressed data
; -------------------------------------------------------------------------

; PCD is used throughout this subroutine as an initialism for Process_Compressed_Data
Nem_ProcessCompressedData:
	move.w	d6, d7
	subq.w	#8, d7		; get shift value
	move.w	d5, d1
	lsr.w	d7, d1		; shift so that high bit of the code is in bit position 7
	cmpi.b	#$FC, d1	; are the high 6 bits set?
	bcc.s	Nem_PCD_InlineData	; if they are, it signifies inline data
	andi.w	#$FF, d1
	add.w	d1, d1
	move.b	(a1,d1.w), d0	; get the length of the code in bits
	ext.w	d0
	sub.w	d0, d6			; subtract from shift value so that the next code is read next time around
	cmpi.w	#9, d6			; does a new byte need to be read?
	bcc.s	+				; if not, branch
	addq.w	#8, d6
	asl.w	#8, d5
	move.b	(a0)+, d5		; read next byte
+
	move.b	$1(a1,d1.w), d1
	move.w	d1, d0
	andi.w	#$F, d1			; get palette index for pixel
	andi.w	#$F0, d0

Nem_PCD_GetRepeatCount:
	lsr.w	#4, d0			; get repeat count

Nem_PCD_WritePixel:
	lsl.l	#4, d4			; shift up by a nybble
	or.b	d1, d4			; write pixel
	subq.w	#1, d3			; has an entire 8-pixel row been written?
	bne.s	Nem_PCD_WritePixel_Loop	; if not, loop
	jmp	(a3)				; otherwise, write the row to its destination


Nem_PCD_NewRow:
	moveq	#0, d4			; reset row
	moveq	#8, d3			; reset nybble counter
Nem_PCD_WritePixel_Loop:
	dbf	d0, Nem_PCD_WritePixel
	bra.s	Nem_ProcessCompressedData


Nem_PCD_InlineData:
	subq.w	#6, d6			; 6 bits needed to signal inline data
	cmpi.w	#9, d6
	bcc.s	+
	addq.w	#8, d6
	asl.w	#8, d5
	move.b	(a0)+, d5
+
	subq.w	#7, d6			; and 7 bits needed for the inline data itself
	move.w	d5, d1
	lsr.w	d6, d1			; shift so that low bit of the code is in bit position 0
	move.w	d1, d0
	andi.w	#$F, d1			; get palette index for pixel
	andi.w	#$70, d0		; high nybble is repeat count for pixel
	cmpi.w	#9, d6
	bcc.s	Nem_PCD_GetRepeatCount
	addq.w	#8, d6
	asl.w	#8, d5
	move.b	(a0)+, d5
	bra.s	Nem_PCD_GetRepeatCount

Nem_PCD_WriteRowToVDP:
	move.l	d4, (a4)		; write 8-pixel row
	subq.w	#1, a5
	move.w	a5, d4			; have all the 8-pixel rows been written?
	bne.s	Nem_PCD_NewRow	; if not, branch
	rts						; otherwise the decompression is finished

Nem_PCD_WriteRowToVDP_XOR:
	eor.l	d4, d2			; XOR the previous row by the current row
	move.l	d2, (a4)		; and write the result
	subq.w	#1, a5
	move.w	a5, d4
	bne.s	Nem_PCD_NewRow
	rts

Nem_PCD_WriteRowToRAM:
	move.l	d4, (a4)+
	subq.w	#1, a5
	move.w	a5, d4
	bne.s	Nem_PCD_NewRow
	rts

Nem_PCD_WriteRowToRAM_XOR:
	eor.l	d4, d2
	move.l	d2, (a4)+
	subq.w	#1, a5
	move.w	a5, d4
	bne.s	Nem_PCD_NewRow
	rts

; -------------------------------------------------------------------------
; Part of the Nemesis decompressor, builds the code table (in RAM)
; -------------------------------------------------------------------------

; BCT is used throughout this subroutine as an initialism for Build_Code_Table
Nem_BuildCodeTable:
	move.b	(a0)+, d0	; read first byte

Nem_BCT_ChkEnd:
	cmpi.b	#$FF, d0	; has the end of the code table description been reached?
	bne.s	Nem_BCT_NewPalIndex	; if not, branch
	rts					; otherwise, this subroutine's work is done

Nem_BCT_NewPalIndex:
	move.w	d0, d7

Nem_BCT_Loop:
	move.b	(a0)+, d0		; read next byte
	cmpi.b	#$80, d0		; sign bit being set signifies a new palette index
	bcc.s	Nem_BCT_ChkEnd	; a bmi could have been used instead of a compare and bcc
	move.b	d0, d1
	andi.w	#$F, d7			; get palette index
	andi.w	#$70, d1		; get repeat count for palette index
	or.w	d1, d7			; combine the two
	andi.w	#$F, d0			; get the length of the code in bits
	move.b	d0, d1
	lsl.w	#8, d1
	or.w	d1, d7			; combine with palette index and repeat count to form code table entry
	moveq	#8, d1
	sub.w	d0, d1			; is the code 8 bits long?
	bne.s	Nem_BCT_ShortCode	; if not, a bit of extra processing is needed
	move.b	(a0)+, d0		; get code
	add.w	d0, d0			; each code gets a word-sized entry in the table
	move.w	d7, (a1,d0.w)	; store the entry for the code
	bra.s	Nem_BCT_Loop	; repeat
; --------------------------------------------------------------------------

; the Nemesis decompressor uses prefix-free codes (no valid code is a prefix of a longer code)
; e.g. if 10 is a valid 2-bit code, 110 is a valid 3-bit code but 100 isn't
; also, when the actual compressed data is processed the high bit of each code is in bit position 7
; so the code needs to be bit-shifted appropriately over here before being used as a code table index
; additionally, the code needs multiple entries in the table because no masking is done during compressed data processing
; so if 11000 is a valid code then all indices of the form 11000XXX need to have the same entry
Nem_BCT_ShortCode:
	move.b	(a0)+, d0		; get code
	lsl.w	d1, d0			; shift so that high bit is in bit position 7
	add.w	d0, d0			; get index into code table
	moveq	#1, d5
	lsl.w	d1, d5
	subq.w	#1, d5			; d5 = 2^d1 - 1
Nem_BCT_ShortCode_Loop:
	move.w	d7, (a1,d0.w)	; store entry
	addq.w	#2, d0
	dbf	d5, Nem_BCT_ShortCode_Loop		; repeat for required number of entries
	bra.s	Nem_BCT_Loop
; -----------------------------------------------------------------


; -------------------------------------------------------------------------
; Adds pattern load requests to the Nemesis decompression queue
; -------------------------------------------------------------------------
LoadPLC:
	movem.l	d0-d2/a1-a3, -(sp)
	add.w	d0, d0
	move.w	(a1,d0.w), d0
	lea	(a1,d0.w), a1
	lea	(Nem_Decomp_Queue).w, a2

	moveq	#$3F, d0
ClearNemQueueLoop:
	move.w	#0, (a2)+
	dbf	d0, ClearNemQueueLoop

	lea	(Nem_Decomp_Queue).w, a2
	move.w	(a1)+, d0
	bmi.s	+
	movea.l	(a1)+, a3
	move.l	a3, (a2)+	; store compressed data location
	move.w	d1, (a2)+	; store destination in VRAM
	subq.w	#1, d0
	bmi.s	+

-
	move.w	(a3), d2	; get VRAM offset
	andi.w	#$7FFF, d2
	lsl.w	#5, d2
	add.w	d2, d1
	movea.l	(a1)+, a3
	move.l	a3, (a2)+	; store compressed data location
	move.w	d1, (a2)+	; store destination in VRAM
	dbf	d0, -
+
	movem.l	(sp)+, d0-d2/a1-a3
	rts
; -----------------------------------------------------------------


; -------------------------------------------------------------------------
; Initializes Nemesis decompression queue processing (art to VRAM)
; -------------------------------------------------------------------------
NemQueueInit_RowToVDP:
	tst.l	(Nem_Decomp_Queue).w
	beq.s	++			; return if the queue is empty
	tst.w	(Nem_Patterns_Left).w
	bne.s	++			; return if processing of a previous piece is still going on
	movea.l	(Nem_Decomp_Queue).w, a0
	lea	(Nem_PCD_WriteRowToVDP).l, a3
	lea	(Nem_Code_Table).w, a1
	move.w	(a0)+, d2
	bpl.s	+
	adda.w	#Nem_PCD_WriteRowToVDP_XOR-Nem_PCD_WriteRowToVDP, a3
+
	andi.w	#$7FFF, d2
	move.w	d2, (Nem_Patterns_Left).w
	bsr.w	Nem_BuildCodeTable
	move.b	(a0)+, d5
	asl.w	#8, d5
	move.b	(a0)+, d5
	moveq	#$10, d6
	moveq	#0, d0
	move.l	a0, (Nem_Decomp_Queue).w
	move.l	a3, (Nem_Decomp_Vars).w
	move.l	d0, (Nem_Repeat_Count).w
	move.l	d0, (Nem_Palette_Index).w
	move.l	d0, (Nem_Previous_Row).w
	move.l	d5, (Nem_Data_Word).w
	move.l	d6, (Nem_Shift_Value).w
+
	rts
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
; Initializes Nemesis decompression queue processing (art to RAM)
; -------------------------------------------------------------------------
NemQueueInit_RowToRAM:
	tst.l	(Nem_Decomp_Queue).w
	beq.s	++
	tst.w	(Nem_Patterns_Left).w
	bne.s	++
	movea.l	(Nem_Decomp_Queue).w, a0
	lea	(Nem_PCD_WriteRowToRAM).l, a3
	lea	(Nem_Code_Table).w, a1
	move.w	(a0)+, d2
	bpl.s	+
	adda.w	#Nem_PCD_WriteRowToRAM_XOR-Nem_PCD_WriteRowToRAM, a3
+
	andi.w	#$7FFF, d2
	move.w	d2, (Nem_Patterns_Left).w
	bsr.w	Nem_BuildCodeTable
	move.b	(a0)+, d5
	asl.w	#8, d5
	move.b	(a0)+, d5
	moveq	#$10, d6
	moveq	#0, d0
	move.l	a0, (Nem_Decomp_Queue).w
	move.l	a3, (Nem_Decomp_Vars).w
	move.l	d0, (Nem_Repeat_Count).w
	move.l	d0, (Nem_Palette_Index).w
	move.l	d0, (Nem_Previous_Row).w
	move.l	d5, (Nem_Data_Word).w
	move.l	d6, (Nem_Shift_Value).w
+
	rts
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
ProcessNemQueue:
	tst.w	(Nem_Patterns_Left).w
	beq.s	ProcessNemQueueDone
	lea	(VDP_Control_Port).l, a4
	move.w	(Nem_Decomp_Destination).w, d0
	andi.l	#$FFFF, d0
	lsl.l	#2, d0
	lsr.w	#2, d0
	ori.w	#$4000, d0
	swap	d0
	move.l	d0, (a4)
	subq.w	#4, a4
	movea.l	(Nem_Decomp_Queue).w, a0
	movea.l	(Nem_Decomp_Vars).w, a3
	move.l	(Nem_Repeat_Count).w, d0
	move.l	(Nem_Palette_Index).w, d1
	move.l	(Nem_Previous_Row).w, d2
	move.l	(Nem_Data_Word).w, d5
	move.l	(Nem_Shift_Value).w, d6
	lea	(Nem_Code_Table).w, a1
	move.w	(Nem_Frame_Patterns_Left).w, (Saved_Nem_Frame_Patterns_Left).w

ProcessNemQueueLoop:
	movea.w	#8, a5
	bsr.w	Nem_PCD_NewRow
	subq.w	#1, (Nem_Patterns_Left).w
	beq.s	ProcessNemQueue_ShiftUp
	subq.w	#1, (Saved_Nem_Frame_Patterns_Left).w
	bne.s	ProcessNemQueueLoop

	move.l	a0, (Nem_Decomp_Queue).w
	move.l	a3, (Nem_Decomp_Vars).w
	move.l	d0, (Nem_Repeat_Count).w
	move.l	d1, (Nem_Palette_Index).w
	move.l	d2, (Nem_Previous_Row).w
	move.l	d5, (Nem_Data_Word).w
	move.l	d6, (Nem_Shift_Value).w
	move.w	(Nem_Frame_Patterns_Left).w, d5
	lsl.w	#5, d5
	add.w	d5, (Nem_Decomp_Destination).w
ProcessNemQueueDone:
	rts
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
ProcessNemQueue_ShiftUp:
	lea	(Nem_Decomp_Queue).w, a0
	moveq	#$B, d0
-
	move.l	$6(a0), (a0)+
	dbf	d0, -
	rts
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
ProcessNemQueue2:
	tst.w	(Nem_Patterns_Left).w
	beq.s	ProcessNemQueue2Done
	movea.l	($FFFFE480).w, a4
	movea.l	(Nem_Decomp_Queue).w, a0
	movea.l	(Nem_Decomp_Vars).w, a3
	move.l	(Nem_Repeat_Count).w, d0
	move.l	(Nem_Palette_Index).w, d1
	move.l	(Nem_Previous_Row).w, d2
	move.l	(Nem_Data_Word).w, d5
	move.l	(Nem_Shift_Value).w, d6
	lea	(Nem_Code_Table).w, a1
	move.w	(Nem_Frame_Patterns_Left).w, (Saved_Nem_Frame_Patterns_Left).w
loc_41A3A:
	movea.w	#8, a5
	bsr.w	Nem_PCD_NewRow
	subq.w	#1, (Nem_Patterns_Left).w
	beq.s	ProcessNemQueue_ShiftUp2
	subq.w	#1, (Saved_Nem_Frame_Patterns_Left).w
	bne.s	loc_41A3A
	move.l	a0, (Nem_Decomp_Queue).w
	move.l	a3, (Nem_Decomp_Vars).w
	move.l	d0, (Nem_Repeat_Count).w
	move.l	d1, (Nem_Palette_Index).w
	move.l	d2, (Nem_Previous_Row).w
	move.l	d5, (Nem_Data_Word).w
	move.l	d6, (Nem_Shift_Value).w
	move.l	a4, ($FFFFE480).w
	move.w	(Nem_Frame_Patterns_Left).w, d5
	lsl.w	#5, d5
	add.w	d5, (Nem_Decomp_Destination).w
	rts


; -------------------------------------------------------------------------
ProcessNemQueue2Done:
	clr.b	($FFFFE486).w
	rts
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
ProcessNemQueue_ShiftUp2:
	lea	(Nem_Decomp_Queue).w, a0
	moveq	#$B, d0
-
	move.l	$6(a0), (a0)+
	dbf	d0, -
	rts
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
; Enigma decompression subroutine
; Inputs:
; a0 = compressed data location
; a1 = destination (in RAM)
; d0 = starting art tile
; See http://www.segaretro.org/Enigma_compression for format description
; -------------------------------------------------------------------------
EniDecomp:
	movem.l	d0-d7/a1-a5, -(sp)
	movea.w	d0, a3	; store starting art tile
	move.b	(a0)+, d0
	ext.w	d0
	movea.w	d0, a5	; store number of bits in inline copy value
	move.b	(a0)+, d0
	ext.w	d0
	ext.l	d0
	ror.l	#1, d0
	ror.w	#1, d0
	move.l	d0, d4	; store PCCVH flags bitfield
	movea.w	(a0)+, a2
	adda.w	a3, a2	; store incremental copy word
	movea.w	(a0)+, a4
	adda.w	a3, a4	; store literal copy word
	move.b	(a0)+, d5
	asl.w	#8, d5
	move.b	(a0)+, d5	; get first word in format list
	moveq	#$10, d6	; initial shift value

EniDecompLoop:
	moveq	#7, d0	; assume a format list entry is 7 bits
	move.w	d6, d7
	sub.w	d0, d7
	move.w	d5, d1
	lsr.w	d7, d1
	andi.w	#$7F, d1	; get format list entry
	move.w	d1, d2	; and copy it
	cmpi.w	#$40, d1	; is the high bit of the entry set?
	bcc.s	+
	moveq	#6, d0	; if it isn't, the entry is actually 6 bits
	lsr.w	#1, d2
+
	bsr.w	EniDecomp_FetchByte
	andi.w	#$F, d2	; get repeat count
	lsr.w	#4, d1
	add.w	d1, d1
	jmp	EniDecom_JumpTbl(pc,d1.w)
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
EniDecomp_00:
	move.w	a2, (a1)+	; copy incremental copy word
	addq.w	#1, a2	; increment it
	dbf	d2, EniDecomp_00	; repeat
	bra.s	EniDecompLoop
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
EniDecomp_01:
	move.w	a4, (a1)+	; copy literal copy word
	dbf	d2, EniDecomp_01	; repeat
	bra.s	EniDecompLoop
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
EniDecomp_100:
	bsr.w	EniDecomp_FetchInlineValue

-
	move.w	d1, (a1)+	; copy inline value
	dbf	d2, -	; repeat
	bra.s	EniDecompLoop
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
EniDecomp_101:
	bsr.w	EniDecomp_FetchInlineValue

-
	move.w	d1, (a1)+	; copy inline value
	addq.w	#1, d1	; increment
	dbf	d2, -	; repeat
	bra.s	EniDecompLoop
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
EniDecomp_110:
	bsr.w	EniDecomp_FetchInlineValue

-
	move.w	d1, (a1)+	; copy inline value
	subq.w	#1, d1	; decrement
	dbf	d2, -	; repeat
	bra.s	EniDecompLoop
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
EniDecomp_111:
	cmpi.w	#$F, d2
	beq.s	EniDecomp_Done

-
	bsr.w	EniDecomp_FetchInlineValue	; fetch new inline value
	move.w	d1, (a1)+	; copy it
	dbf	d2, -	; repeat
	bra.s	EniDecompLoop
; -------------------------------------------------------------------------



; -------------------------------------------------------------------------
EniDecom_JumpTbl:
	bra.s	EniDecomp_00
	bra.s	EniDecomp_00
	bra.s	EniDecomp_01
	bra.s	EniDecomp_01
	bra.s	EniDecomp_100
	bra.s	EniDecomp_101
	bra.s	EniDecomp_110
	bra.s	EniDecomp_111
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
EniDecomp_Done:
	subq.w	#1, a0	; go back by one byte
	cmpi.w	#$10, d6
	bne.s	+
	subq.w	#1, a0	; and another one if needed
+
	move.w	a0, d0
	lsr.w	#1, d0
	bcc.s	+
	addq.w	#1, a0	; make sure it's an even address
+
	movem.l	(sp)+, d0-d7/a1-a5
	rts
; -------------------------------------------------------------------------


; -------------------------------------------------------------------------
; Part of the Enigma decompressor
; Fetches an inline copy value and stores it in d1
; -------------------------------------------------------------------------
EniDecomp_FetchInlineValue:
	move.w	a3, d3
	swap	d4
	bpl.s	+
	subq.w	#1, d6
	btst	d6, d5
	beq.s	+
	ori.w	#$1000, d3
+
	swap	d4
	bpl.s	+
	subq.w	#1, d6
	btst	d6, d5
	beq.s	+
	ori.w	#$800, d3
+
	move.w	d5, d1
	move.w	d6, d7
	sub.w	a5, d7
	bcc.s	loc_41BA4
	move.w	d7, d6
	addi.w	#$10, d6
	neg.w	d7
	lsl.w	d7, d1
	move.b	(a0), d5
	rol.b	d7, d5
	add.w	d7, d7
	and.w	EniDecomp_Masks-2(pc,d7.w), d5
	add.w	d5, d1
loc_41B92:
	move.w	a5, d0
	add.w	d0, d0
	and.w	EniDecomp_Masks-2(pc,d0.w), d1
	add.w	d3, d1
	move.b	(a0)+, d5
	lsl.w	#8, d5
	move.b	(a0)+, d5
	rts
loc_41BA4:
	beq.s	+
	lsr.w	d7, d1
	move.w	a5, d0
	add.w	d0, d0
	and.w	EniDecomp_Masks-2(pc,d0.w), d1
	add.w	d3, d1
	move.w	a5, d0
	bra.s	EniDecomp_FetchByte
+
	moveq	#$10, d6
	bra.s	loc_41B92


; ===================================
EniDecomp_Masks:
	dc.w	1
	dc.w	3
	dc.w	7
	dc.w	$F
	dc.w	$1F
	dc.w	$3F
	dc.w	$7F
	dc.w	$FF
	dc.w	$1FF
	dc.w	$3FF
	dc.w	$7FF
	dc.w	$FFF
	dc.w	$1FFF
	dc.w	$3FFF
	dc.w	$7FFF
	dc.w	$FFFF
; ===================================


; -------------------------------------------------------------------------
; Part of the Enigma decompressor, fetches the next byte if needed
; -------------------------------------------------------------------------
EniDecomp_FetchByte:
	sub.w	d0, d6	; subtract length of current entry from shift value so that next entry is read next time around
	cmpi.w	#9, d6	; does a new byte need to be read?
	bcc.s	+	; if not, branch
	addq.w	#8, d6
	asl.w	#8, d5
	move.b	(a0)+, d5
+
	rts

; -------------------------------------------------------------------------
; Kosinski decompression subroutine
; Inputs:
; a0 = compressed data location
; a1 = destination
; -------------------------------------------------------------------------
KosDecomp:
	subq.l	#2, sp			; make space for two bytes on the stack
	move.b	(a0)+, $1(sp)
	move.b	(a0)+, (sp)
	move.w	(sp), d5		; copy first description field
	moveq	#$F, d4			; 16 bits in a byte

KosDecomp_Loop:
	lsr.w	#1, d5			; bit which is shifted out goes into C flag
	move	sr, d6
	dbf	d4, KosDecomp_ChkBit
	move.b	(a0)+, $1(sp)
	move.b	(a0)+, (sp)
	move.w	(sp), d5		; get next description field if needed
	moveq	#$F, d4			; reset bit counter

KosDecomp_ChkBit:
	move	d6, ccr			; was the bit set?
	bcc.s	KosDecomp_Match	; if not, branch (C flag clear means bit was clear)
	move.b	(a0)+, (a1)+	; otherwise, copy byte as-is
	bra.s	KosDecomp_Loop

KosDecomp_Match:
	moveq	#0, d3
	lsr.w	#1, d5			; get next bit
	move	sr, d6
	dbf	d4, KosDecomp_ChkBit2
	move.b	(a0)+, $1(sp)
	move.b	(a0)+, (sp)
	move.w	(sp), d5
	moveq	#$F, d4

KosDecomp_ChkBit2:
	move	d6, ccr			; was the bit set?
	bcs.s	KosDecomp_FullMatch		; if it was, branch
	lsr.w	#1, d5
	dbf	d4, +
	move.b	(a0)+, $1(sp)
	move.b	(a0)+, (sp)
	move.w	(sp), d5
	moveq	#$F, d4

+
	roxl.w	#1, d3			; get high repeat count bit (shift X flag in)
	lsr.w	#1, d5
	dbf	d4, +
	move.b	(a0)+, $1(sp)
	move.b	(a0)+, (sp)
	move.w	(sp), d5
	moveq	#$F, d4
+
	roxl.w	#1, d3			; get low repeat count bit
	addq.w	#1, d3
	moveq	#-1, d2
	move.b	(a0)+, d2
	bra.s	KosDecomp_MatchLoop

KosDecomp_FullMatch:
	move.b	(a0)+, d0		; get first byte
	move.b	(a0)+, d1		; get second byte
	moveq	#-1, d2
	move.b	d1, d2
	lsl.w	#5, d2
	move.b	d0, d2			; calculate offset
	andi.w	#7, d1			; does a third byte need to be read?
	beq.s	KosDecomp_FullMatch2		; if it does, branch
	move.b	d1, d3			; copy repeat count
	addq.w	#1, d3			; and increment it

KosDecomp_MatchLoop:
	move.b	(a1,d2.w), d0
	move.b	d0, (a1)+		; copy appropriate byte
	dbf	d3, KosDecomp_MatchLoop	; and repeat the copying
	bra.s	KosDecomp_Loop

KosDecomp_FullMatch2:
	move.b	(a0)+, d1
	beq.s	KosDecomp_Done		; 0 indicates end of compressed data
	cmpi.b	#1, d1
	beq.w	KosDecomp_Loop	; 1 indicates a new description needs to be read
	move.b	d1, d3			; otherwise, copy repeat count
	bra.s	KosDecomp_MatchLoop
KosDecomp_Done:
	addq.l	#2, sp			; restore stack pointer to original state
	rts
