	movem.l	d0-d2/a0-a2, -(sp)
	subq.w	#1, d1
	subq.w	#1, d2

PlaneMapToRAM_Row:
	movea.l	a1, a2
	move.w	d1, d7

PlaneMapToRAM_Cell:
