; ==================================================================
; Store DMA transfers in memory to be processed later during V Int
;
; d0 = source address divided by 2
; d1 = VDP destination address
; d2 = transfer length in words
; ==================================================================
QueueDMACommands:
	movem.l	d0-d3/a0, -(sp)
	lea	(DMA_Commands_Buffer).w, a0
	move.w	(DMA_Commands_Buf_Slot).w, d3
	lsl.w	#4, d3
	adda.w	d3, a0
	move.b	#$93, (a0)+	; transfer length low byte (& $00FF)
	move.b	d2, (a0)+
	move.b	#$94, (a0)+	; transfer length high byte (& $FF00)
	lsr.w	#8, d2
	move.b	d2, (a0)+
	move.b	#$95, (a0)+	; source address is address >> 1
	move.b	d0, (a0)+
	move.b	#$96, (a0)+
	lsr.l	#8, d0
	move.b	d0, (a0)+
	move.b	#$97, (a0)+
	lsr.l	#8, d0
	andi.b	#$7F, d0
	move.b	d0, (a0)+
	move.w	d1, d0
	andi.w	#$3FFF, d0	; get VDP address bits
	ori.w	#$4000, d0	; VRAM write command
	move.w	d0, (a0)+
	rol.w	#2, d1
	andi.w	#3, d1	; VDP lowest address bits
	ori.w	#$80, d1	; DMA command bit
	move.w	d1, (a0)+
	addq.w	#1, (DMA_Commands_Buf_Slot).w
	movem.l	(sp)+, d0-d3/a0
	rts

CheckDMAQueue:
	move.w	(DMA_Commands_Buf_Slot).w, d0
	dbeq	d0, ProcessDMAQueue	; if there are no commands (d0 = 0), return, otherwise process the DMA queue
	rts

ProcessDMAQueue:
	lea	(DMA_Commands_Buffer).w, a0
	ori.b	#$10, (VDP_Reg1_Val+1).w	; enable DMA
	move.w	(VDP_Reg1_Val).w, (a6)
DMAQueueLoop:
	move.l	(a0)+, (a6)	; transfer length
	move.l	(a0)+, (a6)	; source address, low word
	move.w	(a0)+, (a6)	; source address, high byte
	move.w	(a0)+, (a6)	; VDP destination address high word
	move.w	(a0)+, (a6)	; VDP destination address low word

	; the part below moves the first word of source address to the Data Port. This is done
	; in some other places where DMA transfer from 68k to VDP is performed...I don't think it's of any use
	moveq	#0, d3
	move.b	-$5(a0), d3	; move high byte of source
	swap	d3			; move it to high word
	move.b	-$7(a0), d3	; lower byte of source
	lsl.w	#8, d3
	move.b	-$9(a0), d3	; lowest byte of source
	add.l	d3, d3	; multiply by 2 to get address
	movea.l	d3, a2
	move.l	-$4(a0), d1	; get VDP destination address
	bclr	#7, d1		; clear DMA transfer bit
	move.l	d1, (a6)	; write to VDP Control Port
	move.w	(a2), (a5)	; write first word of source address to VDP Data Port

	addq.w	#2, a0
	dbf	d0, DMAQueueLoop

	andi.b	#$EF, (VDP_Reg1_Val+1).w	; disable DMA
	move.w	(VDP_Reg1_Val).w, (a6)
	clr.w	(DMA_Commands_Buf_Slot).w	; clear buffer slots
	rts

