MainGameVDPSetup:
	lea	(VDPSetupValues).l, a0
	move.w	$2(a0), (VDP_Reg1_Val).w
	move.w	$18(a0), (VDP_Reg12_Val).w
	moveq	#(VDPSetupValues_End-VDPSetupValues)/2-1, d7
-
	move.w	(a0)+, $4(a5)
	dbf	d7, -

	moveq	#0, d0
	move.l	d0, (Camera_X_Pos_FG).w
	move.l	d0, (Camera_Y_Pos_FG).w
	move.l	d0, (Camera_X_Pos_BG).w
	move.l	d0, (Camera_Y_Pos_BG).w
	move.l	#$C0000000, (VDP_Control_Port).l	; write to CRAM
	move.w	#$3F, d7
-
	move.w	d0, (a5)	; clear CRAM
	dbf	d7, -

	move.w	#$100, (Z80_Bus_Request).l	; Stop the Z80
-
	btst	#0, (Z80_Bus_Request).l
	bne.s	-		; loop until the Z80 has stopped

	ori.b	#$10, (VDP_Reg1_Val+1).w	; Enable DMA
	move.w	(VDP_Reg1_Val).w, (a6)

	; DMA VRAM fill - Clear all the VRAM
	move.w	#$8F01, (a6)	; VDP auto-increment = 1
	move.l	#$93FF94FF, (a6)	; DMA length = $FFFF
	move.w	#$9780, (a6)	; set to VRAM fill
	move.l	#$40000080, (a6)	; write to VRAM with DMA
	move.w	#0, (a5)	; move 0 to Data Port...done for the whole VRAM
-
	btst	#1, $1(a6)	; is DMA taking place?
	bne.s	-			; if so, wait until it's done

	move.l	#$40000000, (a6)	; write to VRAM
	move.w	#0, (a5)
	move.w	#$8F02, (a6)	; auto-increment = 2
	andi.b	#$EF, (VDP_Reg1_Val+1).w	; disable DMA
	move.w	(VDP_Reg1_Val).w, (a6)
	clr.w	(Z80_Bus_Request).l		; start the Z80
	rts

