	dc.w	$8004	; HInt off, Enable HV counter read
	dc.w	$8124	; Enable V Interrupt, disable DMA
	dc.w	$8230	; Scroll A Address $C000
	dc.w	$8300	; Window Address 0
	dc.w	$8407	; Scroll B Address $E000
	dc.w	$8578	; Sprite Table Address $F000
	dc.w	$8600	; Null
	dc.w	$8700	; Background color Pal 0 Color 0
	dc.w	$8800	; Null
	dc.w	$8900	; Null
	dc.w	$8A00	; Hint timing 0 scanlines
	dc.w	$8B00	; Ext Int off, VScroll full, HScroll full
	dc.w	$8C81	; 40 cell mode, shadow/highlight off, no interlace
	dc.w	$8D3D	; HScroll Table Address $F400
	dc.w	$8E00	; Null
	dc.w	$8F02	; VDP auto increment 2 bytes
	dc.w	$9001	; 64x32 cell scroll size
	dc.w	$9100	; Window H left side, Base Point 0
	dc.w	$9200	; Window V upside, Base Point 0
VDPSetupValues_End:
; =====================================================================================


