UpdateRNGSeed:
	movem.l	d0-d1, -(sp)
	move.l	(RNG_Seed).w, d1
	tst.w	d1
	bne.s	+
	move.l	#$2A6D365B, d1
+
	move.l	d1, d0	; multiply d1 by 41
	add.l	d1, d1
	add.l	d1, d1
	add.l	d0, d1
	asl.l	#3, d1
	add.l	d0, d1


	move.w	d1, d0	; sum of low and high word of d1
	swap	d1
	add.w	d1, d0
	move.w	d0, d1	; move sum to d1
	swap	d1		; move it to high word
	move.l	d1, (RNG_Seed).w	; update RNG
	movem.l	(sp)+, d0-d1
	rts
; ----------------------------------------------------------


