RunTitleFadingText:
	lea	(Palette_Table_Buffer+$3E).w, a0
	move.b	(FadeControl).w, d0
	lsr.b	#2, d0
	lsr.b	#1, d0	; check bit 2
	bcc.s	+
	bsr.w	FadingText_DoFadeInLine1
+
	lsr.b	#1, d0	; bit 3
	bcc.s	+
	bsr.w	FadingText_DoFadeInLine2
	lea	(Palette_Table_Buffer+$3E).w, a0
+
	lsr.b	#1, d0	; bit 4
	bcc.s	+
	bsr.w	FadingText_DoFadeOutLine1
	lea	(Palette_Table_Buffer+$3E).w, a0
+
	lsr.b	#1, d0	; bit 5
	bcc.s	+
	bsr.w	FadingText_DoFadeOutLine2
	lea	(Palette_Table_Buffer+$3E).w, a0
+
	rts

