	move.l	#Mappings_RedCursor, mappings(a4)
	move.w	#0, facing_dir(a4)
	bset	#4, render_flags(a4)
	move.b	#$40, $13(a4)
	move.w	#$6E8, $16(a4)
	move.w	#$19, timer(a4)
	bclr	#1, render_flags(a4)	; set object to visible

RedCursor_Main:
	subq.w	#1, timer(a4)	; subtract 1 to timer
	bpl.s	+			; branch if positive
	move.w	#$F, timer(a4)	; reset timer
	bchg	#1, render_flags(a4)	; flip visibility bit
	bne.s	+			; if it was set (invisible), branch
	addi.w	#$A, timer(a4)	; increment timer so that cursor remains invisible for a longer time
+
	bra.w	FieldObj_Animate2
