FieldObj_Chaz:
	bset	#7, (a4)
	bne.s	FieldObj_ChazMain
	move.l	#SprMapsPtrs_Chaz, mappings_addr(a4)
	move.l	#Mappings_CharIdleDown, mappings(a4)
	move.b	#$40, $13(a4)
	moveq	#0, d0
