FieldObj_GetInput:
	cmpi.w	#$C, (Game_Mode_Routine).w
	beq.w	FieldObj_GetAutoInput		; branch if we're processing an event
	moveq	#0, d3		; index of character in the object list
	move.w	a4, d0	; get RAM address of this character
	lea	(Field_Objects_Memory).w, a1
-
	cmp.w	a1, d0	; find the character on the field object list
	beq.s	+	; branch if character found
	lea	$40(a1), a1	; next spot on the object list
	addq.w	#1, d3	; increase index
	bra.s	-

+
	tst.w	d3
	bne.s	FieldObj_GetAutoInput	; branch if this is not the leading character
	move.b	(Joypad_Held).w, d0
	andi.w	#ButtonUp_Mask|ButtonDown_Mask|ButtonLeft_Mask|ButtonRight_Mask, d0
	rts

FieldObj_GetAutoInput:
	moveq	#0, d0
	btst	#1, (Char_Move_Flags).w
	bne.s	loc_4768C
	bsr.w	loc_47698
	bne.s	loc_47696
	bsr.w	loc_476E2
	bra.s	loc_47696

