	move.w	d3, facing_dir(a4)
loc_479A2:
	rts
; ------------------------------------------------------


FieldObj_UpdateStepDuration:
	move.l	x_step_constant(a4), d1
	beq.s	loc_479B4
	bpl.s	loc_479AE
	neg.l	d1
loc_479AE:
	asr.l	#8, d1
	sub.w	d1, x_step_duration(a4)
loc_479B4:
	move.l	y_step_constant(a4), d1
	beq.s	loc_479C4
	bpl.s	loc_479BE
	neg.l	d1
loc_479BE:
	asr.l	#8, d1
	sub.w	d1, y_step_duration(a4)
loc_479C4:
	move.w	x_step_duration(a4), d1
	bmi.w	loc_479D6	; branch if we're done moving
	move.w	y_step_duration(a4), d2
	bmi.w	loc_479D6	; branch if we're done moving
	rts

loc_479D6:
	move.w	x_step_duration(a4), d1
	beq.s	loc_479F4
	ext.l	d1
	asl.l	#8, d1
	tst.l	x_step_constant(a4)
	bpl.s	loc_479E8
	neg.l	d1
loc_479E8:
	add.l	d1, x_step_constant(a4)
	moveq	#0, d1
	move.l	d1, x_step_duration(a4)
	rts
loc_479F4:
	move.w	y_step_duration(a4), d1
	ext.l	d1
	asl.l	#8, d1
	tst.l	y_step_constant(a4)
	bpl.s	loc_47A04
	neg.l	d1
loc_47A04:
	add.l	d1, y_step_constant(a4)
	moveq	#0, d1
	move.l	d1, x_step_duration(a4)
	rts


; -----------------------------------------
FieldObj_UpdateStatus:
	btst	#1, status(a0)	; is character paralyzed?
	bne.s	+					; if so, branch
	btst	#2, status(a0)	; is character dead?
	beq.s	++					; if not, return
+
	move.b	#6, mappings_duration(a4)
	clr.b	mappings_idx(a4)
	bset	#6, $2(a4)
+
	rts
; -----------------------------------------


; -----------------------------------------
FieldObj_FacePlayer:
	lea	(Character_1).w, a3	; player's address
	move.w	curr_x_pos(a4), d0	; x vector
	sub.w	curr_x_pos(a3), d0
	bpl.s	+
	neg.w	d0
+
	move.w	curr_y_pos(a4), d1	; y vector
	sub.w	curr_y_pos(a3), d1
	bpl.s	+
	neg.w	d1
+
	cmp.w	d1, d0
	beq.s	+	; if x and y vectors are the same, don't do anything
	bls.s	.facedown	; if x vector is lower than y, branch

	moveq	#0, d0
	move.w	curr_x_pos(a3), d1	; player's x position
	sub.w	curr_x_pos(a4), d1
	bmi.s	.faceleft

	move.w	#8, d0
	bra.s	.updatefacingdir

.faceleft:
	move.w	#$C, d0
	bra.s	.updatefacingdir

.facedown:
	moveq	#0, d0
	move.w	curr_y_pos(a3), d1	; player's y position
	sub.w	curr_y_pos(a4), d1
	bmi.s	.faceup
	bra.s	.updatefacingdir

.faceup:
	move.w	#4, d0


.updatefacingdir:
	move.w	d0, facing_dir(a4)

+
	moveq	#0, d3
	move.l	d3, x_step_constant(a4)
	move.l	d3, y_step_constant(a4)
	move.b	d3, mappings_idx(a4)
	move.b	#1, mappings_duration(a4)
	bset	#6, render_flags(a4)
	bsr.w	FieldObj_UpdatePosition
	bsr.w	FieldObj_CalcSpritePos
	bra.w	FieldObj_Animate
; -----------------------------------------



