; NPC scripted to move to a certain position
FieldObj_NPCScriptMove:
	bset	#7, (a4)
	bne.s	loc_483C2
	move.l	#loc_4A504, $8(a4)
	move.l	#loc_4A7D0, $C(a4)
	move.b	#4, $11(a4)
	moveq	#0, d0
	move.l	d0, $28(a4)
	bset	#3, $2(a4)
	move.b	#$60, $13(a4)
	move.w	$30(a4), $38(a4)
	move.w	$34(a4), $3A(a4)
loc_483C2:
	bsr.w	FieldObj_GetInput
	bsr.w	FieldObj_Move
	bsr.w	FieldObj_UpdateStepDuration
	bsr.w	FieldObj_UpdatePosition
	bsr.w	FieldObj_CalcSpritePos
	bsr.w	FieldObj_Animate2
	rts
loc_483DC:
	bset	#7, (a4)
	bne.s	loc_48416
	move.l	#loc_4A504, $8(a4)
	move.l	#loc_4A7D0, $C(a4)
	move.b	#4, $11(a4)
	moveq	#0, d0
	move.l	d0, $28(a4)
	bset	#3, $2(a4)
	bset	#6, $2(a4)
	move.w	$30(a4), $38(a4)
	move.w	$34(a4), $3A(a4)
loc_48416:
	bsr.w	FieldObj_GetInput
	bsr.w	FieldObj_Move
	bsr.w	FieldObj_UpdateStepDuration
	bsr.w	FieldObj_UpdatePosition
	bsr.w	FieldObj_CalcSpritePos
	bsr.w	FieldObj_Animate
	rts


; -------------------------------------------------------
; NPC's facing down in a fixed position
; -------------------------------------------------------
FieldObj_NPCType1:
	bset	#7, (a4)
	bne.s	FieldObj_NPCType1Main
	move.l	#loc_4A504, mappings_addr(a4)
	move.l	#loc_4A7D0, mappings(a4)
	move.b	#4, mappings_duration(a4)
	move.b	#$60, $13(a4)
	moveq	#0, d0
	move.l	d0, x_step_duration(a4)
	move.w	#$1000, x_max_move_boundary(a4)
	move.w	#$800, x_move_boundary(a4)
	bset	#3, render_flags(a4)

FieldObj_NPCType1Main:
	bsr.w	FieldObj_OnScreenTest
	bne.s	+	; branch if off-screen
	bsr.w	FieldObj_NPCMoveDown
	moveq	#0, d7
	bsr.w	FieldObj_NPCMove
	bsr.w	FieldObj_UpdateStepDuration
	bsr.w	FieldObj_UpdatePosition
+
	bsr.w	FieldObj_CalcSpritePos
	tst.b	offscreen_flag(a4)
	bne.s	+
	bsr.w	FieldObj_Animate2
+
	rts
; -------------------------------------------------------


; -------------------------------------------------------
; NPC's that move
; -------------------------------------------------------
FieldObj_NPCType2:
	bset	#7, (a4)
	bne.s	loc_484CC
	move.l	#loc_4A504, $8(a4)
	move.l	#loc_4A7D0, $C(a4)
	move.b	#$60, $13(a4)
	move.b	#4, $11(a4)
	moveq	#0, d0
	move.l	d0, $28(a4)
	move.w	#$404, $3C(a4)
	move.w	#$202, $3E(a4)
	bset	#3, $2(a4)
loc_484CC:
	bsr.w	FieldObj_OnScreenTest
	bne.s	loc_484E4	; if object is off-screen, branch
	bsr.w	FieldObj_GetRandomMove
	moveq	#0, d7
	bsr.w	FieldObj_NPCMove
	bsr.w	FieldObj_UpdateStepDuration
	bsr.w	FieldObj_UpdatePosition
loc_484E4:
	bsr.w	FieldObj_CalcSpritePos
	tst.b	$12(a4)	; is object on-screen?
	bne.s	loc_484F2	; if not, branch
	bsr.w	FieldObj_Animate2
loc_484F2:
	rts
; -------------------------------------------------------



