GetMapLayoutOffset:
	tst.w	d3
	bne.s	+
	move.b	(Map_Row_Size_FG).w, d3
	lea	(Map_Layout_FG).w, a1
	bra.s	++
+
	move.b	(Map_Row_Size_BG).w, d3
	lea	(Map_Layout_BG).w, a1
+
	ext.w	d3
	addq.w	#1, d3
	mulu.w	d3, d2
	add.w	d2, d1
	adda.w	d1, a1
	rts
; ---------------------------------------------------


