; -----------------------------------------------------------------
; Draw tiles for Plane A
; -----------------------------------------------------------------
RefreshPlaneFG:
	move.b	(Map_Row_Size_FG).w, (Saved_Map_Row_Size+1).w
	move.b	(Map_Column_Size_FG).w, (Saved_Map_Column_Size+1).w
	move.w	(Field_Map_Index).w, d0
	andi.w	#$FFFE, d0
	bne.s	+
	move.w	#$7F, (Saved_Map_Row_Size).w
	move.w	#$1F, (Saved_Map_Column_Size).w
+
	move.w	(Camera_X_Pos_FG).w, d5
	lsr.w	#5, d5		; get chunk number
	bsr.w	AdjustRowChunkNum
	move.w	d5, d2
	move.w	(Camera_Y_Pos_FG).w, d6
	lsr.w	#5, d6		; get chunk column
	bsr.w	AdjustChunkColumn
	moveq	#7, d1	; (32/4)-1; plane rows
-
	move.w	#$F, d0	; (64/4)-1; plane cells

-
	movem.l	d0-d2, -(sp)
	bsr.w	SetupChunksFG
	movem.l	(sp)+, d0-d2
	addq.w	#1, d5	; next chunk
	bsr.w	AdjustRowChunkNum
	dbf	d0, -

	move.w	d2, d5
	addq.w	#1, d6	; next column
	bsr.w	AdjustChunkColumn
	dbf	d1, --
	rts
; -----------------------------------------------------------------


