; -----------------------------------------------------------------
; Draw tiles offscreen only when you move (Plane A) 
; -----------------------------------------------------------------
RefreshTilesAsYouMoveFG:
	move.b	(Map_Row_Size_FG).w, (Saved_Map_Row_Size+1).w
	move.b	(Map_Column_Size_FG).w, (Saved_Map_Column_Size+1).w
	move.w	(Field_Map_Index).w, d0
	andi.w	#$FFFE, d0
	bne.s	+
	move.w	#$7F, (Saved_Map_Row_Size).w
	move.w	#$1F, (Saved_Map_Column_Size).w
+
	move.w	(Camera_X_Pos_FG).w, d5
	lsr.w	#5, d5		; chunk number
	move.w	d5, (Saved_Chunk_Number).w
	move.w	(Camera_Y_Pos_FG).w, d6
	lsr.w	#5, d6		; chunk column
	move.w	d6, (Saved_Chunk_Column).w
	bclr	#0, (Map_X_Refresh_Flags_FG).w
	beq.w	.checky
	btst	#7, (Camera_X_Step_Counter_FG).w
	bne.s	.cont		; branch if we're moving left
	addi.w	#$E, d5			; otherwise go far past the right edge of the screen
.cont:
	moveq	#7, d3
	bsr.w	AdjustRowChunkNum
	bsr.w	AdjustChunkColumn
	movem.w	d3/d5-d6, -(sp)

.setuploop:
	move.l	d3, -(sp)
	bsr.w	SetupChunksFG
	move.l	(sp)+, d3
	addq.w	#1, d6
	bsr.w	AdjustChunkColumn
	dbf	d3, .setuploop
	movem.w	(sp)+, d3/d5-d6

.drawloop:
	move.l	d3, -(sp)
	bsr.w	DrawChunksFG
	move.l	(sp)+, d3
	addq.w	#1, d6
	bsr.w	AdjustChunkColumn
	dbf	d3, .drawloop

.checky:
	move.w	(Saved_Chunk_Number).w, d5
	move.w	(Saved_Chunk_Column).w, d6
	bclr	#0, (Map_Y_Refresh_Flags_FG).w
	beq.w	.return
	btst	#7, (Camera_Y_Step_Counter_FG).w
	bne.s	.cont2
	addq.w	#7, d6
.cont2:
	move.w	#$F, d3
	bsr.w	AdjustRowChunkNum
	bsr.w	AdjustChunkColumn
	movem.w	d3/d5-d6, -(sp)

.setuploop2:
	move.l	d3, -(sp)
	bsr.w	SetupChunksFG
	move.l	(sp)+, d3
	addq.w	#1, d5
	bsr.w	AdjustRowChunkNum
	dbf	d3, .setuploop2

	movem.w	(sp)+, d3/d5-d6
	moveq	#0, d0
	move.w	d6, d0
	andi.w	#7, d0
	lsl.w	#8, d0
	lsl.w	#1, d0
	move.w	d0, d1
	addi.l	#Plane_A_Buffer, d0
	lsr.l	#1, d0
	addi.w	#$C000, d1
	move.w	#$100, d2
	jsr	(QueueDMACommands).l
.return:
	rts
; -----------------------------------------------------------------


