; -----------------------------------------------------------------
; d5 = Camera X / 32
; d6 = Camera Y / 32
; -----------------------------------------------------------------
DrawChunksFG:
	move.w	d5, d1
	move.w	d6, d0
	andi.w	#7, d0
	andi.w	#$F, d1
	lsl.w	#3, d1
	lsl.w	#8, d0
	lsl.w	#1, d0
	add.w	d1, d0
	addi.w	#$C000, d0
	jsr	(LoadVRAMAddress).l
	move.l	d1, d0
	moveq	#0, d3
	move.w	d6, d3
	moveq	#0, d4
	move.b	(Map_Row_Size_FG).w, d4
	addq.w	#1, d4
	mulu.w	d4, d3
	add.w	d5, d3
	addi.l	#Map_Layout_FG, d3
	movea.l	d3, a1
	moveq	#0, d3
	move.b	(a1), d3
	lsl.w	#5, d3
	moveq	#3, d1
	moveq	#3, d2
	lea	(Chunk_Table).l, a1
	lea	(a1,d3.w), a1
	bra.w	ChunkTilesToVRAM
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d5 = Camera X / 32
; d6 = Camera Y / 32
