	andi.w	#7, d0
	andi.w	#$F, d1
	lsl.w	#3, d1
	lsl.w	#8, d0
	lsl.w	#1, d0
	add.w	d1, d0
	addi.w	#$E000, d0
	jsr	(LoadVRAMAddress).l
	move.l	d1, d0
	moveq	#0, d3
	move.w	d6, d3
	moveq	#0, d4
	move.b	(Map_Row_Size_BG).w, d4
	addq.w	#1, d4
	mulu.w	d4, d3
	add.w	d5, d3
	addi.l	#Map_Layout_BG, d3
	movea.l	d3, a1
	moveq	#0, d3
	move.b	(a1), d3
	lsl.w	#5, d3
	moveq	#3, d1
	moveq	#3, d2
	lea	(Chunk_Table).l, a1
	lea	(a1,d3.w), a1
	tst.b	(BG_Alternate_Color_Flag).w
	bne.s	loc_543D6
	bra.w	ChunkTilesToVRAM
loc_543D6:
	bra.w	ChunkTilesToVRAM2
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d5 = Camera X / 32
; d6 = Camera Y / 32
; -----------------------------------------------------------------
SetupChunksFG:
	moveq	#0, d0
	moveq	#0, d1
	move.w	d5, d1
	move.w	d6, d0
	andi.w	#7, d0	; d0 = plane rows in chunks ; (32/4)-1
	andi.w	#$F, d1	; d1 = plane cells in chunks ; (64/4)-1
	lsl.w	#3, d1	; get plane cell offset
	lsl.w	#8, d0
	lsl.w	#1, d0	; get plane row offset
	add.w	d1, d0	; d0 = get VRAM offset
	addi.l	#Plane_A_Buffer, d0
	movea.l	d0, a2	; a2 = Plane buffer
	moveq	#0, d3
	move.w	d6, d3
	moveq	#0, d4
	move.b	(Map_Row_Size_FG).w, d4
	addq.w	#1, d4
	mulu.w	d4, d3	; map column
	add.w	d5, d3	; d3 = map offset
	addi.l	#Map_Layout_FG, d3
	movea.l	d3, a1	; a1 = Map Layout offset
	moveq	#0, d3
	move.b	(a1), d3	; d3 = chunk ID
	lsl.w	#5, d3		; chunk size
	moveq	#3, d1
	moveq	#3, d2
	lea	(Chunk_Table).l, a1
	lea	(a1,d3.w), a1
	bra.w	ChunkTilesToBuffer
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d5 = Camera X / 32
; d6 = Camera Y / 32
; -----------------------------------------------------------------
SetupChunksBG:
	moveq	#0, d0
	moveq	#0, d1
	move.w	d5, d1
	move.w	d6, d0
	andi.w	#7, d0	; d0 = plane rows in chunks ; (32/4)-1
	andi.w	#$F, d1	; d1 = plane cells in chunks ; (64/4)-1
	lsl.w	#3, d1	; get plane cell offset
	lsl.w	#8, d0
	lsl.w	#1, d0	; get plane row offset
	add.w	d1, d0	; d0 = get VRAM offset
	addi.l	#Plane_B_Buffer, d0
	movea.l	d0, a2	; a2 = Plane buffer
	moveq	#0, d3
	move.w	d6, d3
	moveq	#0, d4
	move.b	(Map_Row_Size_BG).w, d4
	addq.w	#1, d4
	mulu.w	d4, d3	; map column
	add.w	d5, d3	; d3 = map offset
	addi.l	#Map_Layout_BG, d3
	movea.l	d3, a1	; a1 = Map Layout offset
	moveq	#0, d3
	move.b	(a1), d3	; d3 = chunk ID
	lsl.w	#5, d3		; chunk size
	moveq	#3, d1
	moveq	#3, d2
	lea	(Chunk_Table).l, a1
	lea	(a1,d3.w), a1
	tst.b	(BG_Alternate_Color_Flag).w
	bne.s	+
	bra.w	ChunkTilesToBuffer
+
	bra.w	ChunkTilesToBuffer2
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d0 = VRAM address
; d1 = Number of cells
; d2 = Number of rows
; a1 = Chunk table
; a5 = VDP Data Port
; a6 = VDP Control Port
; -----------------------------------------------------------------
ChunkTilesToVRAM:
	move.l	d6, -(sp)
	move.l	#$800000, d7

-
	move.l	d0, (a6)
	move.w	d1, d6
-
	move.w	(a1)+, d3
	andi.w	#$BFFF, d3
	move.w	d3, (a5)
	dbf	d6, -

	add.l	d7, d0
	dbf	d2, --
	move.l	(sp)+, d6
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d1 = Number of cells
; d2 = Number of rows
; a1 = Chunk table
; a2 = Plane buffer
; -----------------------------------------------------------------
ChunkTilesToBuffer:
	move.l	d6, -(sp)
	move.w	#$80, d4	; plane row size
-
	movea.l	a2, a3
	move.w	d1, d6
-
	move.w	(a1)+, d3	; get pattern
	andi.w	#$BFFF, d3	; remove collision bit
	move.w	d3, (a3)+	; store pattern
	dbf	d6, -

	adda.w	d4, a2	; next row
	dbf	d2, --
	move.l	(sp)+, d6
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d0 = VRAM address
; d1 = Number of cells
; d2 = Number of rows
; a1 = Chunk table
; a5 = VDP Data Port
; a6 = VDP Control Port
; -----------------------------------------------------------------
ChunkTilesToVRAM2:
	move.l	d6, -(sp)
	move.l	#$800000, d7

-
	move.l	d0, (a6)
	move.w	d1, d6
-
	move.w	(a1)+, d3
	andi.w	#$1FFF, d3
	move.w	d3, (a5)
	dbf	d6, -

	add.l	d7, d0
	dbf	d2, --
	move.l	(sp)+, d6
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d1 = Number of cells
; d2 = Number of rows
; a1 = Chunk table
; a2 = Plane buffer
; -----------------------------------------------------------------
ChunkTilesToBuffer2:
	move.l	d6, -(sp)
	move.w	#$80, d4	; plane row size
-
	movea.l	a2, a3
	move.w	d1, d6
-
	move.w	(a1)+, d3	; get pattern
	andi.w	#$1FFF, d3	; use first palette line and turn off priority bit 
	move.w	d3, (a3)+	; store pattern
	dbf	d6, -

	adda.w	d4, a2
	dbf	d2, --
	move.l	(sp)+, d6
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d5 = Chunk number in a row
; -----------------------------------------------------------------
AdjustRowChunkNum:
	move.w	(Saved_Map_Row_Size).w, d4
	cmp.w	d4, d5
	bls.s	+

; rollover
	addq.w	#1, d4
	sub.w	d4, d5
	bra.s	AdjustRowChunkNum
+
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d6 = Chunk column
; -----------------------------------------------------------------
AdjustChunkColumn:
	move.w	(Saved_Map_Column_Size).w, d4
	cmp.w	d4, d6
	bls.s	+

; rollover
	addq.w	#1, d4
	sub.w	d4, d6
	bra.s	AdjustChunkColumn
+
	rts
; -----------------------------------------------------------------



