; -----------------------------------------------------------------
XYRange_Null:
	moveq	#0, d7
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
XYRange_XYPlus40:
	move.w	d0, d6	; target x position
	move.w	d1, d7	; target y position
	addi.w	#$40, d6
	addi.w	#$40, d7
	cmp.w	d2, d0
	bhi.s	+		; don't do anything if player's x is lower than target x1 (left)
	cmp.w	d3, d1
	bhi.s	+		; or if player's y is lower than target y1 (up)
	cmp.w	d2, d6
	bls.s	+		; or if player's x is higher than target x2 (right)
	cmp.w	d3, d7
	bls.s	+		; or if player's y is higher than target y2 (down)

	moveq	#1, d7	; otherwise player's position is inside target position
	rts
+
	moveq	#0, d7
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
XYRange_XYPlus20:
	move.w	d0, d6
	move.w	d1, d7
	addi.w	#$20, d6
	addi.w	#$20, d7
	cmp.w	d2, d0
	bhi.s	+
	cmp.w	d3, d1
	bhi.s	+
	cmp.w	d2, d6
	bls.s	+
	cmp.w	d3, d7
	bls.s	+
	moveq	#1, d7
	rts

+
	moveq	#0, d7
	rts
; -----------------------------------------------------------------


