RunEvents:
	movea.l	(Map_Events_Addr).w, a0
	lea	(Character_1).w, a1
	tst.w	$28(a1)		; return if we are moving to a different tile
	bne.w	loc_560DA
	tst.w	$2A(a1)
	bne.w	loc_560DA
loc_560BA:
	cmpi.b	#$FF, (a0)	; did we reach the end of the event list?
	beq.w	loc_560DA	; if so, branch
	moveq	#0, d0
	move.b	(a0), d0
	add.w	d0, d0
	add.w	d0, d0
	lea	RunEventsJmpTbl(pc), a2
	jsr	(a2,d0.w)
	bne.s	loc_560DE		; if event condition is met, flag to run an event
	lea	$1(a0), a0
	bra.s	loc_560BA		; next event index
loc_560DA:
	moveq	#0, d7
	rts

loc_560DE:
	move.w	#$C, (Game_Mode_Routine).w
	moveq	#1, d7
	rts
