RunEvent_Null00:
	moveq	#0, d7
	rts
RunEvent_Null01:
	moveq	#0, d7
	rts
RunEvent_Null02:
	moveq	#0, d7
	rts

RunEvent_FindingAlys:
	move.w	#EventFlag_AlysFound, d0
	jsr	(EventFlags_Test).l
	bne.w	RunEvent_NoEvent		; return if we already found Alys
	lea	(Character_1).w, a4
	move.w	curr_y_pos(a4), d0		; y position
	cmpi.w	#$F0, d0
	bcs.w	RunEvent_NoEvent		; return if y pos is less than $F0
	move.w	curr_x_pos(a4), d0		; x position
	cmpi.w	#$260, d0		; is it $260?
	bne.w	RunEvent_NoEvent		; if not, return
	move.w	#3, (Event_Index).w
	moveq	#1, d7			; flag to run event
	rts

RunEvent_Null04:
	moveq	#0, d7
	rts
RunEvent_Null05:
	moveq	#0, d7
	rts

RunEvent_MachineCenter:
	move.w	#EventFlag_MachineCenter, d0
	jsr	(EventFlags_Test).l
	bne.w	RunEvent_NoEvent	; return if already run
	move.w	#EventFlag_Zio, d0
	jsr	(EventFlags_Test).l
	beq.w	RunEvent_NoEvent	; return if we're not past the event of Zio wounding Alys
	lea	(Character_1).w, a4
	move.w	curr_y_pos(a4), d0	; get y position
	cmpi.w	#$AD0, d0
	bne.w	RunEvent_NoEvent	; return if not $AD0
	move.w	curr_x_pos(a4), d0 ; get x position
	cmpi.w	#$710, d0
	bcs.w	RunEvent_NoEvent	; return if lower than $710
	cmpi.w	#$750, d0
	bhi.w	RunEvent_NoEvent	; return if higher than $750
	move.w	#6, (Event_Index).w
	moveq	#1, d7
	rts

RunEvent_Null07:
	moveq	#0, d7
	rts

RunEvent_BasementContainers:
	move.w	#EventFlag_BasementContainers, d0
	jsr	(EventFlags_Test).l
	bne.w	RunEvent_NoEvent
	move.w	#$C, (Event_Index).w
	moveq	#1, d7
	rts


; ------------------------------------------------------------------
; This code is supposed to run after you meet Saya the first time. The code checks if the event flag ($12) is set;
; If it's not, don't do anything, otherwise always run the event of introducing Saya. This isn't referenced
; anywhere and it doesn't make sense
; ------------------------------------------------------------------
RunEvent_MeetingSayaUnused:
	move.w	#EventFlag_Saya, d0
	jsr	(EventFlags_Test).l
	beq.w	RunEvent_NoEvent
	move.w	#$D, (Event_Index).w
	moveq	#1, d7
	rts

RunEvent_SuspicionOnPrincipal:
	move.w	#EventFlag_PrincipalMeeting, d0
	jsr	(EventFlags_Test).l
	beq.w	RunEvent_NoEvent	; return if we need to talk to the principal for the first time
	move.w	#EventFlag_PrincipalSuspicious, d0
	jsr	(EventFlags_Test).l
	bne.w	RunEvent_NoEvent	; branch if we're past this point
	move.w	#$F, (Event_Index).w
	moveq	#1, d7
	rts

RunEvent_Null0B:
	moveq	#0, d7
	rts

