EventFlags_Test:
	movem.l	d0-d2/a0, -(sp)
	lea	(Event_Flags).w, a0
	bra.s	+

ChestFlags_Test:
	movem.l	d0-d2/a0, -(sp)
	lea	(Chest_Flags).w, a0
	bra.s	+

TempEveFlags_Test:
	movem.l	d0-d2/a0, -(sp)
	lea	(Temp_Event_Flags).w, a0
	bra.s	+

; --------------------------------------------
; TownFlags_Test:
	movem.l	d0-d2/a0, -(sp)
	lea	(Town_Flags).w, a0
; --------------------------------------------

+
	andi.w	#$FF, d0
	move.w	d0, d2
	lsr.w	#3, d0	; get offset
	andi.w	#7, d2	; mask bit to test
	move.w	#7, d1	; 8 bits to select
	sub.w	d2, d1	; get bit
	btst	d1, (a0,d0.w)	; now test
	movem.l	(sp)+, d0-d2/a0
	rts

EventFlags_Set:
	movem.l	d0-d2/a0, -(sp)
	lea	(Event_Flags).w, a0
	bra.s	+

ChestFlags_Set:
	movem.l	d0-d2/a0, -(sp)
	lea	(Chest_Flags).w, a0
	bra.s	+

TempEveFlags_Set:
	movem.l	d0-d2/a0, -(sp)
	lea	(Temp_Event_Flags).w, a0
	bra.s	+

TownFlags_Set:
	movem.l	d0-d2/a0, -(sp)
	lea	(Town_Flags).w, a0

+
	andi.w	#$FF, d0
	move.w	d0, d2
	lsr.w	#3, d0
	andi.w	#7, d2
	move.w	#7, d1
	sub.w	d2, d1
	bset	d1, (a0,d0.w)
	movem.l	(sp)+, d0-d2/a0
	rts

EventFlags_Clear:
	movem.l	d0-d2/a0, -(sp)
	lea	(Event_Flags).w, a0
	bra.s	+

ChestFlags_Clear:
	movem.l	d0-d2/a0, -(sp)
	lea	(Chest_Flags).w, a0
	bra.s	+

TempEveFlags_Clear:
