	lea	(Temp_Event_Flags).w, a0

+
	andi.w	#$FF, d0
	move.w	d0, d2
	lsr.w	#3, d0
	andi.w	#7, d2
	move.w	#7, d1
	sub.w	d2, d1
	bclr	d1, (a0,d0.w)
	movem.l	(sp)+, d0-d2/a0
	rts

; --------------------------------------
