; -----------------------------------------------------------------
FieldRoutine_Controls:
	tst.w	(Vehicle_Index).w	; are we on a vehicle?
	bne.w	FieldRoutine_VehicleControls	; if so, process vehicles instead of characters
	bsr.w	RemoveRedFromPalTable
	lea	(Character_1).w, a4
	tst.w	x_step_duration(a4)
	bne.s	+
	tst.w	y_step_duration(a4)
	bne.s	+
	jsr	(UpdateCharacterStandCollision).l
	jsr	(UpdateCharacterCollision).l
	bsr.w	ChkCharStatsUpdate
+
	btst	#0, (Tile_Coll_Run_Event_Flag).w
	bne.s	+
	bsr.w	RunEvents
	bne.w	++		; branch if flagged to process an event
+
	jsr	(RunMapTransitions).l
	bne.w	+		; branch if flagged to change maps
	bsr.w	RunRandomBattles
	bne.w	+		; branch if flagged to run random battles
	jsr	(FieldControls_GetInput).l
	bne.w	+
	jsr	(Field_UpdateObjects).l
	jsr	(AnimateTiles).l
	jsr	(RunMapUpdates).l
	jsr	(UpdateCameraXPosFG).l
	jsr	(UpdateCameraYPosFG).l
	jsr	(UpdateCameraXPosBG).l
	jsr	(UpdateCameraYPosBG).l
	jsr	(RefreshMapLayout).l
	jsr	(RefreshTilesAsYouMoveFG).l
	jsr	(RefreshTilesAsYouMoveBG).l
+
	bclr	#0, ($FFFFECF6).w
	bne.s	+
	bclr	#1, ($FFFFECF6).w
	bne.s	++
	jmp	(VInt_Prepare).l

+
	jmp	(DMAPlane_A_VInt).l

+
	jmp	(DMAPlane_B_VInt).l
; -----------------------------------------------------------------


; -----------------------------------------------------------------
FieldRoutine_VehicleControls:
	bsr.w	RemoveRedFromPalTable
	lea	(Character_1).w, a4
	tst.w	x_step_duration(a4)
	bne.s	+
	tst.w	y_step_duration(a4)
	bne.s	+
	jsr	(UpdateVehicleStandCollision).l
	jsr	(UpdateVehicleCollision).l
	bsr.w	loc_579FA
+
	jsr	(RunMapTransitions).l
	bne.w	+
	bsr.w	RunEvents
	bne.w	+
	bsr.w	RunRandomBattles
	bne.w	+
	jsr	(loc_56024).l
	bne.w	+
	jsr	(Field_UpdateObjects).l
	jsr	(AnimateTiles).l
	jsr	(RunMapUpdates).l
	jsr	(UpdateCameraXPosFG).l
	jsr	(UpdateCameraYPosFG).l
	jsr	(UpdateCameraXPosBG).l
	jsr	(UpdateCameraYPosBG).l
	jsr	(RefreshMapLayout).l
	jsr	(RefreshTilesAsYouMoveFG).l
	jsr	(RefreshTilesAsYouMoveBG).l
+
	jmp	(VInt_Prepare).l
; -----------------------------------------------------------------


; -----------------------------------------------------------------
RunRandomBattles:
	tst.b	(Random_Battles_Flag).w
	beq.w	NoRandomBattle			; return if flag for the random battles is not set
	cmpi.b	#1, (Tile_Collision_Standing).w		; are we running a scripted event or loading a map?
	beq.w	NoRandomBattle			; if so, return
	cmpi.b	#2, (Tile_Collision_Standing).w		; are we running other events such as stepping on the recovery floor inside the spaceports?
	beq.w	NoRandomBattle			; if so, return
	lea	(Tile_Collision_Up_1).w, a0
	moveq	#7, d1
-
	cmpi.b	#1, (a0)+
	beq.w	NoRandomBattle			; return if we're standing next to a town, dungeon and other such tiles that make you move to different maps
	dbf	d1, -

	lea	(Character_1).w, a4
	tst.w	x_step_duration(a4)
	bne.s	NoRandomBattle			; return if we're advancing to the next tile (x position)
	tst.w	y_step_duration(a4)
	bne.s	NoRandomBattle			; return if we're advancing to the next tile (y position)
	bclr	#0, ($FFFFECE5).w		; clear 'Moving' bit
	beq.s	NoRandomBattle			; if we were already idle, return
	subq.b	#1, ($FFFFECE4).w		; subtract 1 to timer (timer is reset to 10 every time you enter a different map or after a battle)
	bne.s	NoRandomBattle			; return if still above 0
	move.b	#1, ($FFFFECE4).w		; this is to make sure that the branch above won't take place
	jsr	(UpdateRNGSeed).l
	move.w	(RNG_Seed).w, d0
	tst.b	(Vehicle_Index).w
	bne.s	+						; if we're on a vehicle, branch
	andi.w	#$1F, d0				; RNG from 0-31
	bne.s	NoRandomBattle			; if not 0, return
	bra.s	++						; otherwise enter random battle
+
	andi.w	#$7F, d0				; for vehicles RNG is from 0-127
	bne.s	NoRandomBattle
+
	move.w	#$14, (Game_Mode_Routine).w	; FieldRoutine_Battle
	moveq	#1, d0
	rts
NoRandomBattle:
	moveq	#0, d0
	rts
; -----------------------------------------------------------------


ChkCharStatsUpdate:
	cmpi.b	#1, (Tile_Collision_Standing).w
	bne.s	DoCharStatsUpdate
	rts

DoCharStatsUpdate:
	moveq	#0, d6
	bclr	#1, ($FFFFECE5).w
	beq.w	loc_579A8
	addq.b	#1, ($FFFFECE2).w
	andi.b	#3, ($FFFFECE2).w
	addq.b	#1, ($FFFFECE3).w
	lea	(Current_Party_Slots).w, a0
	lea	(Character_Stats).w, a1
	moveq	#0, d0
	moveq	#0, d1
	moveq	#4, d7
loc_578FE:
	move.l	a0, -(sp)
	moveq	#0, d0
	move.b	(a0), d0
	bmi.w	loc_579A6
	lsl.w	#7, d0
	lea	(a1,d0.w), a2	; a2 = current character stats
	tst.b	(Field_Poison_Flag).w
	beq.s	loc_57944
	btst	#StatusPoisoned, status(a2)	; is character poisoned?
	beq.s	loc_57944	; if not, branch
	tst.b	($FFFFECE2).w
	bne.s	loc_57944
	addq.b	#1, d6
	subq.w	#1, curr_hp(a2)
	bne.s	loc_57942		; if character's HP is still not 0, branch
	bclr	#StatusPoisoned, status(a2)	; clear Poisoned bit
	bclr	#StatusParalyzed, status(a2)	; clear Paralyzed bit
	bset	#StatusDead, status(a2)	; set Dead bit
	bsr.w	loc_57A2E
	subq.b	#1, d6
