	moveq	#1, d1
loc_57944:
	btst	#StatusParalyzed, status(a2)	; is character paralyzed?
	beq.s	loc_57972	; if not, branch
	cmpi.b	#5, ($FFFFECE3).w
	bls.s	loc_57972
	cmpi.b	#$19, ($FFFFECE3).w
	bcc.s	loc_5796C
	jsr	(UpdateRNGSeed).l
