; ----------------------------------------------
; Calculate the window ID depending on the number of characters;
; save the character number in memory as well
;
; Return values
;
; d0 = The window ID count to add to the existing one
; ----------------------------------------------
CalcWinIDAndCharNum:
	lea	(Current_Party_Slots).w, a0	; Character ID's
	moveq	#0, d0	; window ID count -- window is chosen based on the number of character; so window ID of 2 is for 5 characters, ID of 3 is for 4 characters and so on
	moveq	#0, d1	; character count
	moveq	#4, d2	; 5 characters
-
	cmpi.b	#$FF, (a0)+	; is there a character in this slot?
	beq.s	+	; if not, branch
	addq.w	#1, d1	; increase character count
	bra.s	++
+
