Pal_IncreaseTone:
	movem.l	d0-d3/a1, -(sp)
	move.w	(Main_Frame_Count).w, d0
	andi.w	#3, d0
	bne.s	Pal_IncreaseToneDone	; only do this every 4 frames
	lea	(Palette_Table_Buffer).w, a1
	move.w	#$3F, d0
Pal_IncreaseToneLoop:
	move.w	(a1)+, d1	; get color
	cmpi.w	#$EEE, d1
	beq.w	Pal_IncreaseToneNextIndex	; if already white, branch
	move.w	d1, d2	; save in d2 for green
	move.w	d1, d3	; save in d3 for blue

	addq.w	#2, d1	; increase red
	andi.w	#$E, d1
	bne.s	+
	move.w	#$E, d1	; cap to $E
+
	addi.w	#$20, d2	; increase green
	andi.w	#$E0, d2
	bne.s	+
	move.w	#$E0, d2	; cap to $E0
+
	addi.w	#$200, d3	; increase blue
	andi.w	#$E00, d3
	bne.s	+
	move.w	#$E00, d3	; cap to $E00
+
	or.w	d2, d1
	or.w	d3, d1
	move.w	d1, -$2(a1)	; update color

Pal_IncreaseToneNextIndex:
	dbf	d0, Pal_IncreaseToneLoop

Pal_IncreaseToneDone:
	movem.l	(sp)+, d0-d3/a1
	rts
