	ext.l	d4
	asl.l	#8, d4
	tst.l	x_step_constant(a4)
	bpl.s	+
	neg.l	d4	; negate the duration if we're moving left
+
	add.l	d4, d3	; add the duration to the player's x
	move.l	curr_y_pos(a4), d4	; now do the same with y position
	moveq	#0, d5
	move.w	y_step_duration(a4), d5
	ext.l	d5
	asl.l	#8, d5
	tst.l	y_step_constant(a4)
