	lsl.w	#3, d5
	move.b	(a1,d5.w), d6
	move.b	$1(a1,d5.w), d7
	tst.w	$2(a1,d5.w)
	bpl.s	+
	neg.w	d6
+
	tst.w	$4(a1,d5.w)
	bpl.s	+
	neg.w	d7
+
	swap	d6
	swap	d7
	add.l	d6, d3
	add.l	d7, d4
	sub.l	d1, d3
	bpl.s	+
	neg.l	d3
+
	cmpi.l	#$80000, d3
	bhi.s	++
	sub.l	d2, d4
	bpl.s	+
	neg.l	d4
+
	cmpi.l	#$80000, d4
