Interaction_ChkMapAreas:
	movea.l	(Map_Interaction_Areas).w, a0

InteractionAreas_Loop:
	cmpi.w	#$FFFF, (a0)
	beq.w	InteractionAreas_None	; branch if we reached the end
	move.w	(a0), d0	; get x position
	move.w	$2(a0), d1	; get y position
	lsl.w	#3, d0		; get effective values
	lsl.w	#3, d1
	move.w	$4(a0), d4	; get index of x and y range table
	add.w	d4, d4
	add.w	d4, d4
	lea	(Character_1).w, a1
	move.w	curr_x_pos(a1), d2	; get x pos of character
	move.w	curr_y_pos(a1), d3	; get y pos
	lea	(InteractionAreas_AdjacentTilePosIncrem).l, a2
	move.w	facing_dir(a1), d5
	lsr.w	#1, d5
	move.b	(a2,d5.w), d6	; increment x position according to player's facing direction
	move.b	$1(a2,d5.w), d7	; same thing with y
	ext.w	d6
	ext.w	d7
	add.w	d6, d2	; add to player's x position
	add.w	d7, d3	; add to player's y position
	lea	(XYRangeJmpTbl).l, a2
	jsr	(a2,d4.w)	; now check range
	bne.s	InteractionAreas_InRange

InteractionAreas_Next:
	lea	$A(a0), a0
	bra.s	InteractionAreas_Loop

InteractionAreas_None:
	moveq	#0, d7
	rts

InteractionAreas_InRange:
	move.b	$7(a0), (Interaction_Event_Flag).w	; store flag (story, chest or temp)
	moveq	#0, d0
	move.b	$7(a0), d0
	move.b	d0, d2
	move.b	$6(a0), (Interaction_Event_Type).w	; get type of event -- 0 = story; 1 = chest; 2 = temp
	moveq	#0, d1
	move.b	$6(a0), d1
	bne.s	+	; if not of type story, branch
	or.b	d1, d2
	beq.s	InteractionAreas_Interacted	; if both type and flag are 0, always display dialogue
	jsr	(EventFlags_Set).l	; test event flag
	bne.s	InteractionAreas_Next	; if it's already happened, don't do anything
	bra.s	InteractionAreas_Interacted

+
	cmpi.b	#1, d1
	bne.s	+		; if not of type chest, branch
	jsr	(ChestFlags_Set).l
	bne.s	InteractionAreas_Next	; if chest was already opened, don't do anything
	bra.s	InteractionAreas_Interacted

+
	jsr	(TempEveFlags_Set).l
	bne.s	InteractionAreas_Next	; if temp flag was set, don't do anything

; if we get here, start processing data upon returning
InteractionAreas_Interacted:
	moveq	#0, d3
	moveq	#0, d4
	move.b	$8(a0), d3	; get interaction type
	move.b	$9(a0), d4	; get index whose value depends on interaction type
	moveq	#1, d7
	rts
