GetItem:
	andi.w	#$FF, d0
	lea	(Inventory).w, a1
	moveq	#0, d1	; count variable
	move.w	#39, d2	; all inventory
-
	tst.b	(a1)+		; is there an item in this spot?
	beq.s	+			; if not, branch
	addq.w	#1, d1		; otherwise add 1 to count
+
	dbf	d2, -	; loop through inventory

	tst.w	d1
	beq.s	ItemNotFound	; if we have no items, return
	subq.w	#1, d1			; subtract 1 for loop
	lea	(Inventory).w, a0
-
	cmp.b	(a0), d0		; did we find item we were looking for?
	beq.s	ItemFound		; if so, return
	lea	$1(a0), a0			; next item
	dbf	d1, -
	bra.s	ItemNotFound	; end of loop -- item not found

ItemFound:
	moveq	#0, d0
	rts

ItemNotFound:
	moveq	#1, d0
	rts
