; -----------------------------------------------------------


; -----------------------------------------------------------
; Gets the stat bonus in inventory data and adds it to the base stat of character
;
; Parameters
;
; d0 = character's base stat
; d1 = offset of item data (stat bonus)
; a1 = address of character's modified stat
; a3 = address of character's equipment
; -----------------------------------------------------------
AddItemBonusToCharStats:
	move.l	a3, -(sp)	; save character equipment address
	moveq	#3, d3
-
	lea	(InventoryData).l, a2
	moveq	#0, d2
	move.b	(a3), d2	; get equipped item
	cmpi.b	#0, d2
	beq.s	+			; branch if character has no equipped item in current slot
	subq.w	#1, d2
	mulu.w	#$16, d2
	lea	(a2,d2.w), a2
	add.b	(a2,d1.w), d0	; add item stat bonus to base stat
+
	lea	$1(a3), a3
	dbf	d3, -

	movea.l	(sp)+, a3
	move.b	d0, (a1)	; move total stat value to character's stats address
	rts
; -----------------------------------------------------------


; -----------------------------------------------------------
; Gets 2 stat bonuses in inventory data and adds it to the base stat of character
;
; Parameters
;
; d0 = character's base stat
; d1 = offset of item data (first stat bonus)
; d2 = offset of item data (second stat bonus)
; a1 = address of character's modified stat
; a3 = address of character's equipment
; -----------------------------------------------------------
AddItemBonusToCharStats2:
	move.l	a3, -(sp)
	moveq	#3, d4
-
	lea	(InventoryData).l, a2
	moveq	#0, d3
	move.b	(a3), d3	; get equipped item
	cmpi.b	#0, d3
	beq.s	+			; branch if character has no equipped item in current slot
	subq.w	#1, d3
	mulu.w	#$16, d3
	lea	(a2,d3.w), a2
	move.b	(a2,d1.w), d5	; stat bonus offset
	ext.w	d5
	add.w	d5, d0			; add stat bonus to base stat
	move.b	(a2,d2.w), d5
	ext.w	d5
	add.w	d5, d0			; add second stat bonus to base stat + first bonus
+
	lea	$1(a3), a3
	dbf	d4, -

	movea.l	(sp)+, a3
	move.w	d0, (a1)
	rts
; -----------------------------------------------------------



; -----------------------------------------------------------
UpdateCharModStatsJmpTbl:
	bra.w	ModStatsUpdate_Strength
	bra.w	ModStatsUpdate_Mental
	bra.w	ModStatsUpdate_Agility
	bra.w	ModStatsUpdate_Dexterity
	bra.w	ModStatsUpdate_Attack
	bra.w	ModStatsUpdate_Defense
	bra.w	ModStatsUpdate_MagicDefense
; -----------------------------------------------------------


ModStatsUpdate_Strength:
	moveq	#0, d0
	move.b	strength(a0), d0
	lea	strength_mod(a0), a1
	move.w	#$B, d1		; item offset = strength bonus
	bra.w	AddItemBonusToCharStats

ModStatsUpdate_Mental:
	moveq	#0, d0
	move.b	mental(a0), d0
	lea	mental_mod(a0), a1
	move.w	#$C, d1		; item offset = mental bonus
	bra.w	AddItemBonusToCharStats

ModStatsUpdate_Agility:
	moveq	#0, d0
	move.b	agility(a0), d0
	lea	agility_mod(a0), a1
	move.w	#$D, d1		; item offset = agility bonus
	bra.w	AddItemBonusToCharStats

ModStatsUpdate_Dexterity:
	moveq	#0, d0
	move.b	dexterity(a0), d0
	lea	dexterity_mod(a0), a1
	move.w	#$E, d1		; item offset = dexterity bonus
	bra.w	AddItemBonusToCharStats

ModStatsUpdate_Attack:
	moveq	#0, d0
	move.b	strength(a0), d0
	lea	atk_pow(a0), a1
	move.w	#$B, d1		; item offset = strength bonus
	move.w	#$F, d2		; item offset = attack bonus
	bra.w	AddItemBonusToCharStats2

ModStatsUpdate_Defense:
	moveq	#0, d0
	move.b	agility(a0), d0
	lea	dfs_pow(a0), a1
	move.w	#$D, d1		; item offset = agility bonus
	move.w	#$10, d2	; item offset = defense bonus
	bra.w	AddItemBonusToCharStats2

ModStatsUpdate_MagicDefense:
	moveq	#0, d0
	move.b	mental(a0), d0
	lea	magic_dfs(a0), a1
	move.w	#$C, d1		; item offset = mental bonus
	move.w	#$11, d2	; item offset = magic defense bonus
	bra.w	AddItemBonusToCharStats2



