ProcessTownTeleportData:
	lea	($FFFFE260).w, a0
	move.w	#8, d7
	trap	#0

	clr.b	($FFFFE284).w
	tst.b	(Dungeon_Teleport_Index).w
	bne.w	loc_604E4
	tst.b	(Town_Teleport_Flag).w
	bne.w	loc_604E4
	move.w	(Town_Flags).w, d0
	lea	(MotaTeleportPlaces).l, a0
	moveq	#$F, d7		; Motavia teleport town number
	cmpi.b	#1, (World_Index).w
	bne.s	+					; branch if not Dezolis
	move.w	(Town_Flags+2).w, d0	; Dezolis town flags
	andi.w	#$FF80, d0
	lea	(DezoTeleportPlaces).l, a0	; get Dezolis places
	moveq	#8, d7		; Dezolis teleport town number
+
	cmpi.b	#2, (World_Index).w
	bne.s	+						; branch if not Rykros
	move.b	(Town_Flags+3).w, d0	; get Rykros places
	andi.w	#$FF, d0
	lsl.w	#8, d0
	lsl.w	#1, d0
	lea	(RykrosTeleportPlaces).l, a0
	moveq	#0, d7		; Rykros teleport town number
+
	cmpi.b	#3, (World_Index).w
	bcc.s	loc_604E4		; return if we're not either Motavia, Dezolis or Rykros
	move.l	a0, ($FFFFE280).w
	lea	($FFFFE260).w, a1
	moveq	#0, d6	; place count
	moveq	#0, d5	; place index

-
	lsl.w	#1, d0
	bcc.s	+
	addq.w	#1, d6	; add 1 to place count
	move.b	d5, (a1)	; store place index
	move.w	d5, d4
	lsl.w	#3, d4
	move.b	(a0,d4.w), $10(a1)
	lea	$1(a1), a1
+
	addq.w	#1, d5
	dbf	d7, -

	move.w	d6, ($FFFFE250).w	; store number of places visited so far
	subq.w	#1, d6
	clr.w	($FFFFE256).w
	divu.w	#5, d6	; divide available place count by 5 (number of entries for teleport window)
	swap	d6		; remainder is on high word so move it to low word
	move.w	d6, ($FFFFE254).w	; store remainder (number of places to display per window)
	swap	d6		; get quotient
	move.w	d6, ($FFFFE252).w	; store it (number of windows to open for teleport list)
	beq.s	+	; branch if only one window
	moveq	#0, d6 ; don't increment index upon returning (window with 5 places will be used)
	rts

+
	swap	d6	; get remainder again
	subq.w	#4, d6
	neg.w	d6	; obtain index that will be added to base window index
	rts

loc_604E4:
	move.b	#1, ($FFFFE284).w
	move.w	#$F, d6
	rts


