; --------------------------------------
; Check if character has enough TP to cast a technique
;
;   Arguments
;
; d0 = TP cost
; d1 = Character ID
; d2 = Flag to determine whether to subtract TP from character or not
;    0 = Subtract TP
;    1 = Don't subtract TP (used to determine if character can use a technique or not)
;
; Return values
;
; d0 = Flag which indicates whether character has enough TP or not
;    0 = Enough TP
;    1 = Not enough TP
; --------------------------------------
SubtractTP:
	movem.l	d0-d1/a0, -(sp)
	andi.w	#$FF, d0
	lea	(Character_Stats).w, a0	; get stats
	lsl.w	#7, d1
	lea	(a0,d1.w), a0
	cmp.w	curr_tp(a0), d0	; is TP cost higher than character's TP?
	bhi.s	++						; if so, branch
	tst.w	d2
	bne.s	+						; branch if we don't want to subtract TP
	sub.w	d0, curr_tp(a0)	; subtract from current TP
+
	moveq	#0, d0					; we have enough TP
	movem.l	(sp)+, d0-d1/a0
	rts
+
	moveq	#1, d0					;  we don't have enough TP
	movem.l	(sp)+, d0-d1/a0
	rts
; --------------------------------------


