RecoverStats:
	movem.l	d0-d1/a0-a2, -(sp)
	lea	(Current_Party_Slots).w, a2	; character ID address
	lea	(Character_Stats).w, a1		; load statistics
	moveq	#4, d0			; 5 characters in your party
-
	moveq	#0, d1
	move.b	(a2)+, d1		; ID of character
	cmpi.b	#$FF, d1		; did we do all characters?
	beq.s	+				; if so, branch
	lsl.w	#7, d1
	lea	(a1,d1.w), a0		; address of current character stats
	bsr.s	DoCharRecovery	; heal this character
	dbf	d0, -				; repeat for next character
+
	bsr.s	DoVehicleRecovery	; now heal vehicles
	movem.l	(sp)+, d0-d1/a0-a2
	rts

DoCharRecovery:
	move.w	max_hp(a0), curr_hp(a0)
	move.w	max_tp(a0), curr_tp(a0)
	move.b	#0, status(a0)		; remove status ailments
	move.b	max_skill_uses(a0), curr_skill_uses(a0)
	move.b	max_skill_uses+2(a0), curr_skill_uses+2(a0)
	move.b	max_skill_uses+4(a0), curr_skill_uses+4(a0)
	move.b	max_skill_uses+6(a0), curr_skill_uses+6(a0)
	move.b	max_skill_uses+8(a0), curr_skill_uses+8(a0)
	move.b	max_skill_uses+10(a0), curr_skill_uses+10(a0)
	move.b	max_skill_uses+12(a0), curr_skill_uses+12(a0)
	move.b	max_skill_uses+14(a0), curr_skill_uses+14(a0)
	rts

