; ----------------------------------------------
; Get the effect (HP or status healing) of items, techniques or skills
;
; Parameters
;
; d0 = ID of item, technique or skill
; d1 = Type used:
;     0 = Technique
;     1 = Skill
;     2 = Item
; a0 = Character stats address (for techniques and skills)
;
; Return values
;
; d0 = Healing value if healing item was used; flag if status healing item was used
; d1 = Healing effect data holding information such as what status to clear
; ----------------------------------------------
GetItemTechSkillEffect:
	andi.w	#$FF, d0
	moveq	#0, d2
	move.l	d2, d3
	cmpi.b	#3, d1
	bcc.s	+	; return if d1 is 3 or above

	cmpi.b	#1, d1
	beq.s	DoSkillEffect
	cmpi.b	#2, d1
	beq.w	DoItemEffect

; Process Technique effect
	lea	(TechniqueData).l, a1
	subq.w	#1, d0
	lsl.w	#3, d0
	lea	(a1,d0.w), a1
	_move.b	0(a1), d2
	bsr.w	GetHealingEffect
	btst	#$F, d1
	bne.w	loc_67F6C
	cmpi.b	#$16, d2
	beq.w	Effect_FullHeal
	move.b	mental_mod(a0), d2	; get character's mental power
	move.b	$3(a1), d3				; get technique power
	bsr.w	CalcHealingValue
+
	rts

DoSkillEffect:
	lea	(SkillData).l, a1
	subq.w	#1, d0
	lsl.w	#3, d0
	lea	(a1,d0.w), a1
	_move.b	0(a1), d2
	bsr.w	GetHealingEffect
	btst	#$F, d1
	bne.s	loc_67F6C
	cmpi.b	#$16, d2
	beq.s	Effect_FullHeal
	moveq	#0, d0
	move.b	$1(a1), d0
	andi.b	#$F, d0
	subq.w	#1, d0
	lea	(loc_67F80).l, a2
	move.b	(a2,d0.w), d0
	move.b	(a0,d0.w), d2
	move.b	$3(a1), d3
	bsr.w	CalcHealingValue
	rts

DoItemEffect:
	lea	(InventoryData).l, a1
	subq.w	#1, d0
	mulu.w	#$16, d0
	lea	(a1,d0.w), a1	; a1 = item address
	_move.b	0(a1), d2	; get item effect
	bsr.w	GetHealingEffect
	btst	#$F, d1
	bne.w	loc_67F6C
	cmpi.b	#$16, d2	; 16 = Full healing
	beq.w	Effect_FullHeal
	move.b	$1(a1), d2	; get "mental" power
	move.b	$3(a1), d3	; get item power
	bsr.w	CalcHealingValue
	rts

loc_67F6C:
	btst	#$B, d1
	bne.s	loc_67F76
	moveq	#0, d0
	rts

loc_67F76:
	moveq	#1, d0
	rts

Effect_FullHeal:
	move.w	#999, d0	; heal 999
	rts

loc_67F80:
	dc.b	$19
	dc.b	$1C
	dc.b	$1F, $22

; ----------------------------------------
GetHealingEffect:
	moveq	#0, d1
	lea	(HealingEffectData).l, a2
	moveq	#6, d7
-
	cmp.b	(a2), d2
	beq.s	+
	addq.w	#4, a2
	dbf	d7, -
	rts
+
	move.b	$1(a2), d1
	add.w	$2(a2), d1
	rts
; ----------------------------------------

; ===================================================================
HealingEffectData:
	dc.b	$12
	dc.b	$0F
	dc.w	$0000

	dc.b	$13
	dc.b	$0E
	dc.w	$8000

	dc.b	$14
	dc.b	$0D
	dc.w	$8000

	dc.b	$15
	dc.b	$00
	dc.w	$8800

	dc.b	$16
	dc.b	$00
	dc.w	$0000

	dc.b	$17
	dc.b	$00
	dc.w	$0000

	dc.b	$18
	dc.b	$0F
	dc.w	$0000
; ===================================================================

; ----------------------------------------
CalcHealingValue:
	moveq	#0, d0	; d0 will hold the total number for healing
	move.l	d0, d4
	move.l	d0, d5
	move.w	d2, d4	; get mental power
	lsr.w	#1, d4	; divide it by 2
	move.w	d0, ($FFFFECD0).w
	moveq	#$F, d7
-
	jsr	(UpdateRNGSeed).l
	move.w	(RNG_Seed).w, d5
	andi.w	#7, d5			; range from 0 to 7
	cmp.w	($FFFFECD0).w, d5
	beq.s	-		; if generated number is the same as previous one, repeat

	move.w	d5, ($FFFFECD0).w	; store newly generated number
	add.w	d5, d0				; add this to total
	dbf	d7, -

	addq.w	#8, d0		; add 8 to total
	mulu.w	d2, d0		; multiply total by item power
	lsr.w	#7, d0		; divide total by 128
	add.w	d4, d0		; add mental (divided by 2) to total
	add.w	d3, d0		; finally add item, technique or skill power to total
	clr.w	($FFFFECD0).w
	rts
; ----------------------------------------


