; -----------------------------------------------------------------
Window_Create:
	if vwf_menu=1
	jsr	(VWFMenu_FlushReveal).l	; deferred reveals resolve against the old group
	endif
	bsr.w	LoadWindowGroup
	move.l	a0, (Win_Group_Start_Addr).w	; save address of window group
	move.w	(Window_Index).w, (Saved_Window_Index).w	; save previous index
	move.w	d0, (Window_Index).w	; store new index
	lea	(Chunk_Table).l, a0
	moveq	#0, d1
	move.b	(Windows_Opened_Num).w, d1
	bne.s	+
	move.w	#$6040, (Win_Saved_Plane_Maps_End).w
+
	add.w	d1, d1
	lea	(a0,d1.w), a0
	moveq	#-1, d1
	move.w	(Win_Saved_Plane_Maps_End).w, d1
	movea.l	d1, a1
	move.w	a1, (a0)
	move.w	d0, (a1)+
	move.w	(Saved_Window_Index).w, (a1)+
	if vwf_menu=1
	move.l	a1, -(sp)		; the backed-up cells start here
	endif
	bsr.w	Window_BackupTiles
	move.w	a1, (Win_Saved_Plane_Maps_End).w
	if vwf_menu=1
	move.l	a1, d1
	movea.l	(sp)+, a0
	sub.l	a0, d1
	lsr.l	#1, d1			; d1 = cells backed up
	jsr	(VWFMenu_SaveMarkPush).l
	jsr	(VWFMenu_SaveRegion).l	; record their keys, then let them go
	jsr	(VWFMenu_Mark).l	; record the pool mark for this window
	else
	endif
	bsr.w	Window_Draw
	addq.b	#1, (Windows_Opened_Num).w
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; Save map tiles that the window is going to overlap
; d0 = window index
; -----------------------------------------------------------------
Window_BackupTiles:
	movea.l	(Win_Group_Start_Addr).w, a0
	moveq	#0, d1
	moveq	#0, d2
	moveq	#0, d3
	moveq	#0, d4
	move.w	d0, d7
	lsl.w	#3, d7
	lea	(a0,d7.w), a0
	move.b	(a0), d1	; width
	move.b	$1(a0), d2	; height
	move.b	$2(a0), d3	; X offset
	move.b	$3(a0), d4	; Y offset
	bsr.w	GetPlaneAOffset
	move.w	d2, d6	; d6 = height
.copyrow:
	movea.l	a0, a2	; a2 = plane A
	move.w	d1, d5	; d5 = width
.copycell:
	move.w	(a2)+, (a1)+
	move.w	a2, d7
	andi.w	#$7F, d7
	bne.s	.nextcell	; branch if we're still in the same row
	lea	-$80(a2), a2	; otherwise go back to the beginning of the row
.nextcell:
	dbf	d5, .copycell

	lea	$80(a0), a0		; next row
	move.w	a0, d7
	andi.w	#$F80, d7
	bne.s	.nextrow 
	lea	-$1000(a0), a0	; plane wrap
.nextrow:
	dbf	d6, .copyrow
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
Window_Draw:
	movea.l	(Win_Group_Start_Addr).w, a0
