Window_Destroy:

; Add a check to prevent RAM corruption if the Windows_Opened_Num value is 0
	if bugfixes=1
	tst.b	(Windows_Opened_Num).w
	beq.s	+
	endif
	subq.b	#1, (Windows_Opened_Num).w
	if vwf_menu=1
	jsr	(VWFMenu_Release).l	; roll the pool back to this window's mark
	else
	endif
	lea	(Chunk_Table).l, a0
	moveq	#0, d0
	move.b	(Windows_Opened_Num).w, d0
	add.w	d0, d0
	lea	(a0,d0.w), a0
	moveq	#-1, d0
	move.w	(a0), d0
	movea.l	d0, a1
	if vwf_menu=1
	move.w	(a1), (VWFMenu_RemapIdx).l	; loc_6881E clobbers d3
	endif
	move.w	a1, (Win_Saved_Plane_Maps_End).w
	bsr.w	loc_6881E
	if vwf_menu=1
	movem.l	d0-d1/a0-a1, -(sp)
	move.w	(VWFMenu_RemapIdx).l, d0
	jsr	(VWFMenu_DeferReveal).l	; repointed before the plane is next sent
	jsr	(VWFMenu_SaveMarkPop).l
	movem.l	(sp)+, d0-d1/a0-a1
	endif
	moveq	#0, d0
	move.b	(Windows_Opened_Num).w, d0
	beq.s	+
	subq.b	#1, d0
	add.w	d0, d0
	lea	(Chunk_Table).l, a0
	lea	(a0,d0.w), a0
	moveq	#-1, d0
	move.w	(a0), d0
	movea.l	d0, a0
	moveq	#0, d0
	move.w	(a0), d0
	move.w	d0, (Window_Index).w
	move.w	$2(a0), d0
	move.w	d0, (Saved_Window_Index).w
+
	rts

