; -----------------------------------------------------------------
; d3 = X offset
; d4 = Y offset
;
; Returns
;
; a0 = Plane A offset
; -----------------------------------------------------------------
GetPlaneAOffset:
	movem.l	d0/a2-a4, -(sp)
	movea.w	(Camera_X_Pos_FG).w, a2
	movea.w	(Camera_Y_Pos_FG).w, a3
	movea.l	#Plane_A_Buffer, a4
	moveq	#0, d5
	move.w	d3, d5	; d5 = X offset
	move.w	d4, d6	; d6 = Y offset
	move.l	a2, d0	; d0 = Camera X FG
	lsr.w	#3, d0
	add.w	d0, d5
	andi.w	#$3F, d5
	add.w	d5, d5	; plane cell size
	move.l	a3, d0	; d0 = Camera Y FG
	lsr.w	#3, d0
	add.w	d0, d6
	andi.w	#$1F, d6
	asl.w	#7, d6	; plane row size
	add.w	d6, d5
	add.l	a4, d5
	movea.l	d5, a0
	movem.l	(sp)+, d0/a2-a4
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
LoadWindowGroup:
	cmpi.w	#$C, (Game_Mode_Index).w	; are we in the field screen?
	bne.s	+					; if not, branch
	moveq	#0, d7
	move.w	(Game_Mode_Routine).w, d7
	lsr.w	#1, d7
	lea	(WinGroupOffsets).l, a0
	move.w	(a0,d7.w), d7
	adda.l	d7, a0		; a0 = window group start address
	rts

+
	lea	(WinGroup_Other).l, a0
	rts
; -----------------------------------------------------------------


; =================================================================
WinGroupOffsets:
	dc.w	WinGroup_Controls-WinGroupOffsets	; 0
	dc.w	WinGroup_Menu-WinGroupOffsets	; 2
	dc.w	WinGroup_Dialogue-WinGroupOffsets	; 4
	dc.w	WinGroup_Event-WinGroupOffsets	; 6
	dc.w	WinGroup_System-WinGroupOffsets	; 8
	dc.w	WinGroup_Battle-WinGroupOffsets	; $A
	dc.w	WinGroup_Shop-WinGroupOffsets	; $C
	dc.w	WinGroup_PlaceName-WinGroupOffsets	; $E
	dc.w	WinGroup_MotaDezoMap-WinGroupOffsets	; $10
	dc.w	WinGroup_TreasureChest-WinGroupOffsets	; $12
; =================================================================



; =================================================================
;        Windows Data
;
; Byte 1 = Width; needs to be > 0 or the game will crash
; Byte 2 = Height; needs to be > 0 or the game will crash
; Byte 3 = X offset
; Byte 4 = Y offset
; Byte 5-8 = Pointer
; =================================================================


; =================================================================
WinGroup_Controls:
	dc.b	$01, $02, $0E, $07	; 0
	dc.l	Win_Generic

	dc.b	$19, $04, $07, $15	; 1
	dc.l	Win_Generic
; =================================================================


; =================================================================
WinGroup_Menu:
	if vwf_menu_chrome=1
	dc.b	$07, $0E, $04, $02	; 0 - 8 cells (was 9): STATUS + cursor fill
					; 7, and nothing else in the group is sized to this
	else
	dc.b	$09, $0E, $04, $02	; 0 - 10 wide (was 9): room for six-letter labels
