Window_Update:
	movea.l	(Win_Group_Start_Addr).w, a0
	move.w	(Window_Index).w, d0
	lsl.w	#3, d0
	lea	(a0,d0.w), a0
	movea.l	$4(a0), a0
	jmp	(a0)
; -----------------------------------------------------------------



Win_Generic:
	movea.l	(Win_Group_Start_Addr).w, a0
	move.w	(Window_Index).w, d0
	lsl.w	#3, d0
	lea	(a0,d0.w), a0
	move.b	$2(a0), d0
	move.b	$3(a0), d1
	addq.w	#1, d0
	addq.w	#1, d1
	move.w	#$C000, d2
	move.w	#0, d3
	moveq	#1, d4
	lea	(loc_69826).l, a0
	bsr.w	LoadWindowTiles
	btst	#ButtonCancel, (Joypad_Pressed).w
	beq.s	loc_69824
	bsr.w	Window_Destroy
	move.w	#0, (Window_Index).w
loc_69824:
	rts

loc_69826:
	dc.b	$83, $94, $8C, $8C, $98, $FF ;0x0 (0x00069826-0x0006982C, Entry count: 0x00000006) [Unknown data]


; -----------------------------------------------------------------
; d0 = X position
; d1 = Y position
; a0 = address of index
; -----------------------------------------------------------------
InitWindowCursor:
	move.w	d0, d2
	lea	(Red_Cursor).w, a4
	move.w	#$34, (a4)	; => FieldObj_RedCursor
	move.w	d2, sprite_x_pos(a4)
	move.w	d1, sprite_y_pos(a4)
	bset	#0, $5(a4)
	move.w	(Camera_X_Pos_FG).w, d0
	andi.w	#7, d0
	sub.w	d0, sprite_x_pos(a4)
	move.w	(Camera_Y_Pos_FG).w, d0
	andi.w	#7, d0
	sub.w	d0, sprite_y_pos(a4)
	moveq	#0, d0
	move.b	(a0), d0
	lsl.w	#4, d0
	add.w	d0, sprite_y_pos(a4)
	rts
; -----------------------------------------------------------------



