Win_UpdateCursorUpDown:
	move.l	d0, -(sp)
	lea	(Red_Cursor).w, a4
	bsr.w	loc_69F3C
	move.l	(sp)+, d0
	move.w	d0, d1
	add.w	d1, d1
	addq.w	#2, d1
	lsl.w	#3, d1 	; y position for cursor to jump from first row to last and vice versa
	btst	#ButtonUp, (Joypad_Pressed).w
	beq.s	+				; branch if Up was not pressed
	move.b	#SFXID_MovingCursor, (Sound_Index).l	; play sound
	move.w	#$19, $1C(a4)		; reset timer for visibility
	bclr	#1, $2(a4)			; set to visible
	subi.w	#$10, $2E(a4)		; subtract 16 to y position
	subq.b	#1, (a0)			; update window option index
	bpl.s	+			; branch if we haven't gone past the first option yet
	move.b	d0, (a0)			; update to last option index
	add.w	d1, $2E(a4)			; and update y position accordingly
+
	btst	#ButtonDown, (Joypad_Pressed).w
	beq.s	+			; branch if Down was not pressed
	move.b	#SFXID_MovingCursor, (Sound_Index).l	; play sound
	move.w	#$19, $1C(a4)		; reset timer for visibility
	bclr	#1, $2(a4)			; set to visible
	addi.w	#$10, $2E(a4)		; add 16 to y position
	addq.b	#1, (a0)			; update window option index
	cmp.b	(a0), d0
	bge.s	+			; branch if we haven't gone past the last option yet
	move.b	#0, (a0)			; update to first option index
	sub.w	d1, $2E(a4)			; and update y position accordingly
+
	rts

