	btst	#ButtonLeft, (Joypad_Pressed).w
	beq.s	loc_6998C		; branch if Left was not pressed
	move.b	#SFXID_MovingCursor, (Sound_Index).l	; play sound
	move.w	#$19, $1C(a4)		; reset timer for visibility
