; -----------------------------------------------------------------
; d4 = render type; 0 = print one letter at the time; 1 = print all text at once
; a0 = text address
; -----------------------------------------------------------------
RunText:
	movem.l	d3-d4/a0, -(sp)
	jsr	FillTextBackground(pc)
	jsr	TextBufferToPlane(pc)
	movem.l	(sp)+, d3-d4/a0
	moveq	#0, d1
	moveq	#0, d2
RunText_CharacterLoop:
	moveq	#0, d0
	move.b	(a0)+, d0
	cmpi.b	#$F0, d0
	bcs.s	.normalcharacter
	move.b	d0, d5
	andi.w	#$F, d5
	add.w	d5, d5
	add.w	d5, d5
	jmp	TextCtrlCodesJmpTbl(pc,d5.w)

.normalcharacter:
	jsr	GetFontGraphics(pc)
	jsr	(VWFDia_DrawGlyph).l	; compose; advances d1 by the glyph width
	tst.w	d4
	bne.w	.addcharoffset
	jsr	(VWFDia_FlushGlyph).l
.addcharoffset:
	tst.w	d5		; room left? (was: 32 characters per line)
	bne.s	.next	; if we didn't reach the end of the line, branch
	cmpi.b	#$F5, (a0)
	bne.s	.addcharline
	lea	$1(a0), a0
	bra.w	TextCtrlCode_YesNo
.addcharline:
	addq.w	#1, d2	; add line
	cmpi.b	#$FC, (a0)
	bne.s	.chkline
	lea	$1(a0), a0
.chkline:
	andi.w	#1, d2		; limit of 2 lines
	beq.w	TextCtrlCode_Interrupt	; if we already printed 2 lines, display the A
.next:
	tst.w	d4
	bne.w	RunText_CharacterLoop
	move.w	(Message_Speed).w, d0
	move.b	(Joypad_Held).w, d5
	andi.w	#ButtonCancel_Mask|ButtonSpeak_Mask|ButtonCamp_Mask|ButtonStart_Mask, d5
	beq.s	.wait
	moveq	#0, d0
.wait:
	jsr	(DMAPlane_A_VInt).l
	dbf	d0, .wait
	bra.w	RunText_CharacterLoop
; -----------------------------------------------------------------


; -----------------------------------------------------------------
TextCtrlCode_Terminate:
	tst.w	d4
	beq.w	loc_6A126
	jsr	TextToVRAM(pc)
loc_6A126:
	jsr	(DMAPlane_A_VInt).l
TextCtrlCode_Terminate2:
	pushdlg
	clr.b	(Render_Sprites_In_Cutscenes).w
	rts
; -----------------------------------------------------------------


