; -----------------------------------------------------------------
; d0 = character
; a0 = text cursor
;
; Returns
;
; a1 = font graphics
; -----------------------------------------------------------------
GetFontGraphics:
	movem.l	d0-d1, -(sp)
	cmpi.b	#$E0, d0
	bcs.s	+
	move.b	(a0)+, d0
+
	move.w	d0, d1
	andi.w	#$7F, d1
	lsl.w	#4, d1
	lea	(Art_DiaFont).l, a1
	lea	(a1,d1.w), a1
	movem.l	(sp)+, d0-d1
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d1 = line offset
; d2 = line number
; d4 = render type
; a1 = font graphics
; -----------------------------------------------------------------
ParseText:
	movem.l	d0-a2, -(sp)
	movea.l	a1, a0
	lea	(Text_Buffer).l, a1
	tst.w	d4
	beq.s	+
	lsl.w	#6, d1
	lsl.w	#8, d2
	lsl.w	#3, d2
	add.w	d2, d1
	lea	(a1,d1.w), a1
+
	move.w	#$F, d0	; white color (for text)
	move.w	#$E, d1	; blue color (for background)
	move.w	#$F, d7	; 16 characters total
.characterloop:
	move.b	(a0)+, d6	; get character
	moveq	#7, d3	; 8 bits
	moveq	#7, d4	; bit number
	moveq	#0, d5
.bitloop:
	lsl.l	#4, d5	; next nybble
	btst	d4, d6
	beq.s	.nocharacter	; branch if not set
	or.w	d0, d5		; use text color if set
	bra.s	.next
.nocharacter:
	or.w	d1, d5		; use background color
.next:
	subq.w	#1, d4	; next bit
	dbf	d3, .bitloop
	move.l	d5, (a1)+
	dbf	d7, .characterloop
	movem.l	(sp)+, d0-a2
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
; d1 = line offset
; d2 = line number
; -----------------------------------------------------------------
TextCharacterToVRAM:
	movem.l	d1-d2, -(sp)
	lsl.l	#6, d1
	lsl.l	#7, d2
	lsl.l	#4, d2
	add.l	d2, d1
	addi.l	#$B000, d1
	move.l	#$7FFFB800, d0	; Text_Buffer
	moveq	#$20, d2
	jsr	(QueueDMACommands).l
	movem.l	(sp)+, d1-d2
	rts
; -----------------------------------------------------------------


; -----------------------------------------------------------------
TextToVRAM:
	movem.l	d0-a2, -(sp)
