Event_AlysFound:
	lea	(Alys_Piata).w, a4
	lea	(Character_1).w, a3
	move.w	curr_y_pos(a3), d0	; character's Y position
	cmp.w	curr_y_pos(a4), d0	; is character's Y position the same as Alys'?
	beq.w	+			; if so, branch

; if Y position is not the same, move her down one tile so she's aligned with Chaz
	moveq	#2, d0
-
	lea	(Alys_Piata).w, a4
	jsr	(FieldObj_NPCAlysPiata).l	; update Alys object
	jsr	(Field_LoadSprites).l
	jsr	(Field_BuildSprites).l
	jsr	(VInt_Prepare).l
	lea	(Alys_Piata).w, a4
	move.w	x_step_duration(a4), d0
	or.w	y_step_duration(a4), d0
	bne.s	-		; wait until Alys has finished moving

+
; update facing direction
	lea	(Alys_Piata).w, a4
	moveq	#FacingDir_Right, d0
	jsr	(Event_UpdateObjFacing).l

; activate dialogue
	lea	(Alys_Piata).w, a4
	move.b	dialogue_id(a4), d0
	jsr	(Event_GetAndRunDialogue).l

	move.w	#(CharID_Alys<<8)|CharID_Chaz, (Current_Party_Slots).w	; switch party positions
	lea	(Alys_Piata).w, a3
	clr.w	(a3)	; we are done with Alys as NPC, so delete it
	lea	(Character_1).w, a0	; copy Chaz properties in the 2nd spot
	lea	(Character_2).w, a1
	move.w	#$1F, d7
	trap	#1

	lea	(Character_2).w, a4
	move.w	#$53C, art_tile(a4)

	lea	(Character_1).w, a4
	lea	(Alys_Piata).w, a3
	move.w	#8, (a4)	; FieldObj_Alys
	move.w	#FacingDir_Left, facing_dir(a4)
	move.w	#$534, art_tile(a4)
	move.w	curr_x_pos(a3), curr_x_pos(a4)
	move.w	curr_y_pos(a3), curr_y_pos(a4)
	move.w	curr_x_pos(a3), dest_x_pos(a4)
	move.w	curr_y_pos(a3), dest_y_pos(a4)
	jsr	(FieldObj_Alys).l

	moveq	#CharID_Alys, d0
	jsr	(Event_AddMacro).l
	lea	(Alys_Piata).w, a0	; clear NPC Alys memory
	move.w	#$F, d7
	trap	#0

	lea	(Character_1).w, a4
	move.w	curr_x_pos(a4), d0
	move.w	curr_y_pos(a4), d1
	moveq	#2, d2
	jsr	(Event_MoveCamera).l
	moveq	#EventFlag_AlysFound, d0
	jmp	(EventFlags_Set).l
; -----------------------------------------------------------------


