Event_MeetingHahn:
	lea	(Hahn_Near_Basement).w, a4
	jsr	(FieldObj_NPCHahnNearBasement).l
	jsr	(Field_LoadSprites).l
	jsr	(Field_BuildSprites).l
	jsr	(VInt_Prepare).l
	lea	(Hahn_Near_Basement).w, a4
	move.w	x_step_duration(a4), d0
	or.w	y_step_duration(a4), d0
	bne.s	Event_MeetingHahn	; wait until Hahn is done updating his position

	lea	(Hahn_Near_Basement).w, a4
	lea	(Character_1).w, a3
	move.w	curr_x_pos(a3), d0
	cmp.w	curr_x_pos(a4), d0	; is Hahn's X pos the same as the character's?
	beq.w	loc_6B42A			; if so, branch
	bhi.s	+			; branch if Hahn is to the left of the character
	moveq	#8, d0				; move Hahn to the left
	bra.s	++
+
	moveq	#4, d0				; move Hahn to the right
/
	lea	(Hahn_Near_Basement).w, a4
	jsr	(FieldObj_NPCHahnNearBasement).l
	jsr	(Field_LoadSprites).l
	jsr	(Field_BuildSprites).l
	jsr	(VInt_Prepare).l
	lea	(Hahn_Near_Basement).w, a4
	move.w	x_step_duration(a4), d0
	or.w	y_step_duration(a4), d0
	bne.s	-

loc_6B42A:
	lea	(Hahn_Near_Basement).w, a4
	moveq	#FacingDir_Down, d0
	jsr	(Event_UpdateObjFacing).l

	moveq	#$11, d0
	jsr	(Event_GetAndRunDialogue).l

	move.b	#CharID_Hahn, (Current_Party_Slot_3).w
	lea	(Character_3).w, a4
	lea	(Hahn_Near_Basement).w, a3
	move.w	#$C, (a4)	; FieldObj_Hahn
	move.w	#FacingDir_Down, facing_dir(a4)
	move.w	#$544, art_tile(a4)
	move.w	curr_x_pos(a3), curr_x_pos(a4)
	move.w	curr_y_pos(a3), curr_y_pos(a4)
	bset	#1, (Char_Move_Flags).w
	jsr	(FieldObj_Hahn).l
	moveq	#CharID_Hahn, d0
	jsr	(Event_AddMacro).l
	lea	(Hahn_Near_Basement).w, a0
	move.w	#$2F, d7
	trap	#0
