Event_ChazHouse:
	if dialogue_uncompressed = 1
; The original swaps the portrait of message $31 from Alys to Chaz once she
; is gone by poking the operand byte in the RAM copy of the tree.  With the
; dialogue uncompressed the tree is read straight from ROM, so that poke was
; a write to ROM and Alys kept greeting the player after her death.  Copy the
; message (and $32, the "no" branch of its YesNo) into the otherwise unused
; Dialogue_Trees buffer, patch the copy, and run it from there.
	move.b	#$31, d0
	jsr	(GetDialogueByID).l
	lea	(Dialogue_Trees).l, a1
	moveq	#2-1, d1		; two $FF-terminated messages
-	move.b	(a0)+, (a1)+
	cmpi.b	#$FF, -1(a1)
	bne.s	-
	dbf	d1, -
	moveq	#EventFlag_Zio, d0
	jsr	(EventFlags_Test).l
	beq.s	+
	move.b	#1, (Dialogue_Trees+1).l	; $F4 operand: Alys -> Chaz
+
	lea	(Dialogue_Trees).l, a0
