; =================================================================
;        Combo Data
;
; Byte 1: Effect
;   1: damage
;   2: death
;   3: attack down
;	4: defense down
;   6: agility down
;   7: sleep
;   8: silence, as the player Seals technique
;   9: attack up
;   $A: defense up
;   $B: magic defense up
;   $C: agility up
;	$D = element resistance up
;	$E = wake up
;   $12: heal HP
;	$13: cure poison
;	$14: cure paralysis
;	$15: revive character
;	$16: full healing
;   $1B: poison
;   $1C: paralyze
;   $1D: android death
;   $21: dexterity down
;   $26: dexterity up
;   $27: restore stats
;   $2B: increase stats by 20
;
; Byte 2: Always 0.
;
; Byte 3: Targetting byte. For combos there are only two values used for this.
;   01: targets an enemy
;   02: targets all enemies
;
; Byte 4: Hit chance; not applicable if byte 5 is 0 or for effects such as damage and healing
;
; Byte 5: Determines which stat to use as resistance for targets
;   1: strength
;   2: mental
;   3: agility
;   4: dexterity
;   5: attack
;   6: defense
;   7: magic defense
;
; Byte 6: Element
;   01: Physical
;   02: Energy
;   03: Fire
;   04: Gravity
;   05: Water/Ice
;   06: Anti-Evil/Holy
;   07: Lightning
;   08: Holyword
;   09: Brose
;   0A: Biological
;   0B: Psychic
;   0C: Mechanical
;   0D: Efess
;   0E: Destroy
;
; Byte 7: Always 0
;
; Byte 8: Always 0
; =================================================================
ComboData:

Combo_None:
	dc.b	$00, $00, $00, $00, $00, $00, $00, $00

Combo_Paradinblw:
	dc.b	$01, $00, $01, $00, $07, $06, $00, $00

Combo_Firestorm:
	dc.b	$01, $00, $02, $00, $07, $03, $00, $00

Combo_Blizzard:
	dc.b	$01, $00, $02, $00, $07, $05, $00, $00

Combo_Condctthnd:
	dc.b	$01, $00, $02, $00, $07, $07, $00, $00

Combo_Grandcross:
	dc.b	$01, $00, $02, $00, $07, $0D, $00, $00

Combo_Silentwave:
	dc.b	$01, $00, $02, $00, $06, $01, $00, $00

Combo_Shootnstar:
	dc.b	$01, $00, $02, $00, $07, $03, $00, $00

Combo_Triblaster:
	dc.b	$01, $00, $02, $00, $07, $02, $00, $00

Combo_Holocaust:
	dc.b	$02, $00, $02, $40, $02, $0A, $00, $00

Combo_BlackHole:
	dc.b	$02, $00, $02, $40, $02, $0E, $00, $00

Combo_Circuitbrk:
	dc.b	$02, $00, $02, $40, $01, $0C, $00, $00

Combo_Purfylight:
	dc.b	$02, $00, $02, $40, $02, $08, $00, $00

Combo_LethalImg:
	dc.b	$02, $00, $02, $40, $02, $0A, $00, $00

Combo_Destruct:
	dc.b	$01, $00, $02, $00, $07, $06, $00, $00


	even


; =================================================================
;               Combo Setup Data
;
; Byte 1: The number of participants. 80 seems to indicate that a combo is
;   order-sensitive.
;
; Byte 2+: This is the index number of the techs and skills needed to activate
;   the combo. Techs use their normal index number, and skills have 0x80 added to
;   distinguish them.
; =================================================================
ComboSetupData:

; Paradinblw
	dc.b	$02
	dc.b	$80|SkillID_Rayblade, $80|SkillID_Astral
	dc.b	$FF

