; =======================================================================================
;       Vehicle Data
;
; Byte 1-2: HP

; Byte 3: Strength
; Byte 4: Mental
; Byte 5: Agility
; Byte 6: Dexterity
; Byte 7: Attack
; Byte 8: Defense
; Byte 9: Magic defense

; Byte 10: Physical properties
;   00: immune
;   01: resistant
;   02: normal
;   03: weak

; Byte 11: Energy properties
; Byte 12: Fire properties
; Byte 13: Gravity properties
; Byte 14: Water properties
; Byte 15: Anti-Evil properties
; Byte 16: Electric properties
; Byte 17: Holyword properties
; Byte 18: Brose properties
; Byte 19: Biological properties
; Byte 20: Psychic properties
; Byte 21: Mechanical properties
; Byte 22: Efess properties
; Byte 23: Destroy properties

; Byte 24: Bitfield - shows which Optin abilities are available to the vehicle.
;   bit 0 = Cluster
;   bit 1 = Gravitn
;   bit 2 = Th.Grid
;   bit 3 = X-Burst
;   bit 4 = Napalm
;   bit 6 = N-Spher
;
;
; Byte 25: Available uses of the first Optin
; Byte 26: Available uses of the second Optin
; =======================================================================================
VehicleData:

Vehicle_LandRover:
	dc.w	$02E4
	dc.b	$40, $00, $3C, $46, $C8, $50, $32, $01, $02, $01, $01, $01
	dc.b	$02, $03, $00, $00, $00, $00, $00, $00, $02
	dc.b	VehicleSkillID_Cluster_Mask|VehicleSkillID_Gravitn_Mask
	dc.b	$08, $08

Vehicle_IceDigger:
	dc.w	$03C0
	dc.b	$50, $00, $30, $46, $FA, $50, $32, $01, $02, $01, $01, $01
	dc.b	$02, $03, $00, $00, $00, $00, $00, $00, $02
	dc.b	VehicleSkillID_Napalm_Mask|VehicleSkillID_NSpher_Mask
	dc.b	$08, $04

Vehicle_Hydrofoil:
	dc.w	$02A8
	dc.b	$FF, $00, $60, $46, $96, $46, $28, $01, $02, $01, $01, $01
	dc.b	$02, $03, $00, $00, $00, $00, $00, $00, $02
	dc.b	VehicleSkillID_ThGrid_Mask|VehicleSkillID_XBurst_Mask
	dc.b	$04, $02


	even

	include	"general/tables/wincharset.asm"

VehicleAttackNames:
	dc.b	"Cluster Bomb", $FF
	dc.b	"Graviton", $FF
	dc.b	"Thunder Grid", $FF
	dc.b	"Zelan Buster", $FF
	dc.b	"Napalm Missile", $FF
	dc.b	"NOTHING", $FF
	dc.b	"Negasphere", $FF
	dc.b	"NOTHING", $FF

	charset

	even


; =======================================================================================
;         Vehicle Skill Data
;
; Byte 1: Effect
;   1: damage
;   2: death
;   3: attack down
;	4: defense down
;   6: agility down
;   7: sleep
;   8: silence, as the player Seals technique
;   9: attack up
;   $A: defense up
;   $B: magic defense up
;   $C: agility up
;	$D = element resistance up
;	$E = wake up
;   $12: heal HP
;	$13: cure poison
;	$14: cure paralysis
;	$15: revive character
;	$16: full healing
;   $1B: poison
;   $1C: paralyze
;   $1D: android death
;   $21: dexterity down
;   $26: dexterity up
;   $27: restore stats
;   $2B: increase stats by 20
;
; Byte 2: Relevant statistic. For vehicles, it's always Strength (aka 1).
;
; Byte 3: Targetting byte. For vehicles, it's always all enemies (aka 2).
;
; Byte 4: Hit chance; not applicable if byte 5 is 0 or for effects such as damage and healing
;
; Byte 5: Determines which stat to use as resistance for targets
;   1: strength
;   2: mental
;   3: agility
;   4: dexterity
;   5: attack
;   6: defense
;   7: magic defense
;
; Byte 6: Element
;   01: Physical
;   02: Energy
;   03: Fire
;   04: Gravity
;   05: Water/Ice
;   06: Anti-Evil/Holy
;   07: Lightning
;   08: Holyword
;   09: Brose
;   0A: Biological
;   0B: Psychic
;   0C: Mechanical
;   0D: Efess
;   0E: Destroy
;
; Byte 7: Always 0
;
; Byte 8: Always 0
; =======================================================================================
VehicleSkillData:

VehicleSkill_Cluster:
	dc.b	$01, $01, $02, $80, $06, $01, $00, $00

VehicleSkill_Gravitn:
	dc.b	$01, $01, $02, $F0, $07, $04, $00, $00

VehicleSkill_ThGrid:
	dc.b	$01, $01, $02, $00, $07, $07, $00, $00

VehicleSkill_XBurst:
	dc.b	$01, $01, $02, $F0, $07, $02, $00, $00

VehicleSkill_Napalm:
	dc.b	$01, $01, $02, $80, $07, $03, $00, $00

VehicleSkill_Nothing:
	dc.b	$01, $01, $02, $80, $06, $01, $00, $00

VehicleSkill_NSpher:
	dc.b	$02, $01, $02, $20, $02, $0E, $00, $00

VehicleSkill_Nothing2:
	dc.b	$01, $01, $02, $80, $06, $01, $00, $00


	even


; ========================================================================
;           Character level tables
;
; Byte 1-4 (4 bytes): Experience needed for this level.

; Byte 5-6: HP
; Byte 7-8: TP

; Byte 9: Strength
; Byte 10: Mental
; Byte 11: Agility
; Byte 12: Dexterity

; Byte 13: New tech learned. This will be added to the top of the character's
;   tech list.
; Byte 14: New skill learned. This will be added to the top of the character's
;   skill list.

; Byte 15-21 (7 bytes): Skill uses for the corresponding skill. This is that
;   number of times that you can use the skills without resting. The first one
;   listed would be the one at the bottom of the skill list. (ie. Chaz at level 6
;   can use Earth 6 times).

; Byte 22: Presumably the skill uses for the eighth skill.
; ========================================================================

