; ---------------------------------------------------------------------
; Prerendered name strips, built by tools/menustrip.py.
;
; Placed past $300000 so nothing below moves: every hardcoded pointer in
; the game keeps its address.  The generator asserts its entry counts
; against the assembled tables, so these cannot drift out of step with
; the names they render without failing the build.
;
; VWFMenu_StripTable holds one word per table - the first index belonging
; to it - so a lookup is table base plus id minus one.
; ---------------------------------------------------------------------
VWFMenu_StripTable:	binclude	"vwf/menustripbase.bin"
	even
VWFMenu_StripMap:	binclude	"vwf/menustripmap.bin"
	even
VWFMenu_StripIdx:	binclude	"vwf/menustripidx.bin"
	even
VWFMenu_StripArt:	binclude	"vwf/menustrips.bin"
	even
	else
; ---------------------------------------------------------------------
; Composed names: the same offset map, plus the translated text in the menu
; charset, built by tools/menustrip.py alongside the strips.  The ROM name
; tables keep the US text - the game walks them by terminator and lays out
; against their character counts - so the translation has to live beside
; them.  Same placement rule as the strips, and for the same reason.
; ---------------------------------------------------------------------
VWFMenu_StripMap:	binclude	"vwf/menustripmap.bin"
	even
VWFMenu_NameIdx:	binclude	"vwf/menunameidx.bin"
	even
VWFMenu_NameText:	binclude	"vwf/menunames.bin"
	even
	endif

	while (*) < $400000
		dc.b	$FF
	endm

